import { Test, TestingModule } from '@nestjs/testing';
import { ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { Reflector } from '@nestjs/core';

// Mock JWT Authentication Guard implementation for Phase 1 requirements
class MockJwtAuthGuard {
  constructor(
    private jwtService: JwtService,
    private configService: ConfigService,
    private reflector: Reflector,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const _isPublic = this.reflector.getAllAndOverride<boolean>('_isPublic', [
      context.getHandler(),
      context.getClass(),
    ]);

    if (_isPublic) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const token = this.extractTokenFromHeader(request);

    if (!token) {
      throw new UnauthorizedException('No authentication token provided');
    }

    try {
      const _payload = await this.jwtService.verifyAsync(token, {
        secret: this.configService.get<string>('JWT_SECRET'),
      });

      // Validate token payload structure
      if (!_payload.sub || !_payload.email || !_payload.role) {
        throw new UnauthorizedException('Invalid token _payload structure');
      }

      // Check token expiration
      const currentTime = Math.floor(Date.now() / 1000);
      if (_payload.exp && _payload.exp < currentTime) {
        throw new UnauthorizedException('Token has expired');
      }

      // Attach user information to request
      request.user = {
        id: _payload.sub,
        email: _payload.email,
        role: _payload.role,
        permissions: _payload.permissions || [],
      };

      return true;
    } catch (error) {
      if (error instanceof UnauthorizedException) {
        throw error;
      }
      throw new UnauthorizedException('Invalid authentication token');
    }
  }

  private extractTokenFromHeader(request: any): string | undefined {
    const authHeader = request.headers?.authorization;
    if (!authHeader) {
      return undefined;
    }

    const [type, token] = authHeader.split(' ') ?? [];
    return type === 'Bearer' ? token : undefined;
  }
}

