      });

      jest.spyOn(reflector, 'getAllAndOverride').mockReturnValue(false);
      jest.spyOn(jwtService, 'verifyAsync').mockResolvedValue({
        sub: 'cleanup_user',
        email: 'cleanup@bytebot.ai',
        role: 'admin',
        exp: Math.floor(Date.now() / 1000) + 3600,
