 * - Cross-origin request validation with CORS security
 * - Real-time permission validation for computer use operations
 * - VNC connection authentication and resource access control
 * - Performance-optimized validation for real-time operations
 * - Comprehensive security context propagation
 *
 * @author JWT Guards BytebotD Specialist
 * @version 2.0.0
 * @since ByteBotd Enhanced JWT Security Implementation
 */

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
  Logger,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { Request, Response } from 'express';
import {
  UserRole,
  Permission as _Permission,
  SecurityEventType as _SecurityEventType,
  createSecurityEvent as _createSecurityEvent,
  JwtPayload,
} from '@bytebot/shared';
import { ByteBotdUser } from './jwt-auth.guard';

/**
 * Enhanced JWT payload with service authentication and refresh capabilities
 */
interface EnhancedJwtPayload extends JwtPayload {
  /** Service identifier for service-to-service authentication */
  serviceId?: string;
  /** Service type (computer-use, agent, ui) */
  serviceType?: string;
  /** Token type (access, refresh, service) */
  tokenType: 'access' | 'refresh' | 'service';
  /** Refresh token identifier */
  refreshTokenId?: string;
  /** Original client IP for security validation */
  clientIp?: string;
  /** VNC session identifier if applicable */
  vncSessionId?: string;
  /** Computer use permissions bitmap */
  computerUsePermissions?: number;
  /** Screen access level (none, view, control) */
  screenAccessLevel?: 'none' | 'view' | 'control';
}

/**
 * Enhanced request interface with security context
 */
interface EnhancedAuthenticatedRequest extends Request {
  user: ByteBotdUser;
  securityContext: {
    tokenRefreshed: boolean;
    serviceAuthentication: boolean;
    vncSessionValid: boolean;
    screenAccessGranted: boolean;
    riskScore: number;
    operationId: string;
  };
}

/**
 * Computer use authorization levels
 */
enum ComputerUsePermission {
  NONE = 0,
  VIEW_SCREEN = 1,
  MOUSE_CONTROL = 2,
  KEYBOARD_CONTROL = 4,
  FILE_ACCESS = 8,
  CLIPBOARD_ACCESS = 16,
  VNC_CONNECTION = 32,
  FULL_CONTROL = 63, // All permissions
}

/**
 * Enhanced JWT Authentication Guard with advanced features
 * Provides comprehensive security for computer automation endpoints
 */
@Injectable()
export class EnhancedJwtAuthGuard extends AuthGuard('jwt') {
  private readonly logger = new Logger(EnhancedJwtAuthGuard.name);

  // Token refresh cache to prevent multiple refresh attempts
  private refreshAttempts = new Map<string, number>();

  // Service authentication cache for performance
  private serviceAuthCache = new Map<
    string,
    { valid: boolean; expires: number }
  >();

  constructor(
    private readonly reflector: Reflector,
    private readonly jwtService: JwtService,
  ) {
    super();

    // Clean up caches every 5 minutes
    setInterval(
      () => {
        this.cleanupCaches();
      },
      5 * 60 * 1000,
    );
  }

  /**
   * Enhanced JWT validation with comprehensive security checks
   * Supports token refresh, service authentication, and real-time validation
   */
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const operationId = `enhanced-jwt-${Date.now()}-${Math.random().toString(36).substr(2, 8)}`;
    const startTime = Date.now();

    // Check if route is public
    const isPublic = this.reflector.getAllAndOverride<boolean>('isPublic', [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      this.logger.debug(
        `[${operationId}] Public route, skipping authentication`,
      );
      return true;
    }

    const request = context
      .switchToHttp()
      .getRequest<EnhancedAuthenticatedRequest>();
    const response = context.switchToHttp().getResponse<Response>();
    const clientIp = this.getClientIpAddress(request);

    // Initialize security context
    request.securityContext = {
      tokenRefreshed: false,
      serviceAuthentication: false,
      vncSessionValid: false,
      screenAccessGranted: false,
      riskScore: 0,
      operationId,
    };

    this.logger.debug(
      `[${operationId}] Enhanced JWT authentication initiated`,
      {
        operationId,
        method: request.method,
        url: request.url,
        clientIp,
        userAgent: request.headers['user-agent']?.substring(0, 100),
        timestamp: new Date().toISOString(),
      },
    );

    // Enhanced pre-authentication security checks
    const securityCheck = await this.performEnhancedSecurityChecks(
      request,
      operationId,
    );
    if (!securityCheck.passed) {
      throw new UnauthorizedException(
        `Enhanced security check failed: ${securityCheck.reason}`,
      );
    }

    try {
      // Attempt primary authentication
      let authResult = await super.canActivate(context);

      if (!authResult) {
        // Try token refresh if primary authentication fails
        authResult = await this.attemptTokenRefresh(
          request,
          response,
          operationId,
        );
      }

      if (authResult && request.user) {
        const authTime = Date.now() - startTime;

        // Perform enhanced post-authentication validation
        await this.performPostAuthValidation(request, operationId);

        // Validate computer use permissions
        await this.validateComputerUsePermissions(request, operationId);

        // Check VNC session if applicable
        await this.validateVncSession(request, operationId);

        // Update security context
        request.securityContext.riskScore = this.calculateRiskScore(request);

        this.logger.log(
          `[${operationId}] Enhanced JWT authentication successful`,
          {
            operationId,
            userId: request.user.id,
            username: request.user.username,
            role: request.user.role,
            authTimeMs: authTime,
            tokenRefreshed: request.securityContext.tokenRefreshed,
            serviceAuth: request.securityContext.serviceAuthentication,
            vncSession: request.securityContext.vncSessionValid,
            screenAccess: request.securityContext.screenAccessGranted,
            riskScore: request.securityContext.riskScore,
            securityEvent: 'enhanced_jwt_auth_success',
          },
        );
      }

      return authResult as boolean;
    } catch (_error) {
      const authTime = Date.now() - startTime;

      this.logger.warn(`[${operationId}] Enhanced JWT authentication failed`, {
        operationId,
        error: _error instanceof Error ? _error.message : String(_error),
        authTimeMs: authTime,
        clientIp,
        securityEvent: 'enhanced_jwt_auth_failed',
        riskScore: 90, // High risk for failed enhanced authentication
      });

      if (
        _error instanceof UnauthorizedException ||
        _error instanceof ForbiddenException
      ) {
        throw _error;
      }

      throw new UnauthorizedException(
        'Enhanced authentication required for computer control',
      );
    }
  }

  /**
   * Attempt automatic token refresh when primary authentication fails
   */
  private async attemptTokenRefresh(
    request: EnhancedAuthenticatedRequest,
    response: Response,
    operationId: string,
  ): Promise<boolean> {
    const refreshToken = this.extractRefreshToken(request);

    if (!refreshToken) {
      this.logger.debug(
        `[${operationId}] No refresh token available for automatic refresh`,
      );
      return false;
    }

    // Check refresh attempt rate limiting
    const clientId = this.getClientIpAddress(request);
    const attempts = this.refreshAttempts.get(clientId) || 0;

    if (attempts >= 3) {
      this.logger.warn(
        `[${operationId}] Too many refresh attempts from client`,
        {
          operationId,
          clientIp: clientId,
          attempts,
          securityEvent: 'excessive_refresh_attempts',
        },
      );
      throw new UnauthorizedException('Too many refresh attempts');
    }

    try {
      // Increment refresh attempts
      this.refreshAttempts.set(clientId, attempts + 1);

      // Validate and decode refresh token
      const refreshPayload =
        await this.jwtService.verifyAsync<EnhancedJwtPayload>(refreshToken, {
          secret: process.env.JWT_REFRESH_SECRET || process.env.JWT_SECRET,
        });

      if (refreshPayload.tokenType !== 'refresh') {
        throw new UnauthorizedException('Invalid token type for refresh');
      }

      // Generate new access token
      const newAccessToken = await this.generateAccessToken(refreshPayload);

      // Set new token in response header
      response.setHeader('X-New-Access-Token', newAccessToken);

      // Create user object for request context
      // Ensure email and id exist, provide fallbacks if not available
      const userId = refreshPayload.sub || `user-${Date.now()}`;
      const email = refreshPayload.email || `${userId}@unknown.local`;
      const user: ByteBotdUser = {
        id: userId,
        email,
        username: email.split('@')[0] || 'unknown-user', // Fallback username from email
        role: refreshPayload.role || UserRole._VIEWER, // Default to VIEWER role if missing
        isActive: true, // Assuming active if refresh is valid
      };

      request.user = user;
      request.securityContext.tokenRefreshed = true;

      this.logger.log(`[${operationId}] Token automatically refreshed`, {
        operationId,
        userId: user.id,
        securityEvent: 'token_auto_refresh',
      });

      // Clear refresh attempts on success
      this.refreshAttempts.delete(clientId);

      return true;
    } catch (_error) {
      this.logger.warn(`[${operationId}] Token refresh failed`, {
        operationId,
        error: _error instanceof Error ? _error.message : String(_error),
        securityEvent: 'token_refresh_failed',
      });

      return false;
    }
  }

  /**
   * Extract refresh token from various request sources
   */
  private extractRefreshToken(request: Request): string | null {
    // Check refresh token in cookies (most secure)
    if (request.cookies?.refreshToken) {
      return request.cookies.refreshToken;
    }

    // Check refresh token in secure headers
    if (request.headers['x-refresh-token']) {
      return request.headers['x-refresh-token'] as string;
    }

    // Check refresh token in request body (for specific endpoints)
    if (request.body?.refreshToken && request.method === 'POST') {
      return request.body.refreshToken;
    }

    return null;
  }

  /**
   * Generate new access token from refresh token payload
   */
  private async generateAccessToken(
    refreshPayload: EnhancedJwtPayload,
  ): Promise<string> {
    const accessPayload: Partial<EnhancedJwtPayload> = {
      sub: refreshPayload.sub,
      email: refreshPayload.email,
      role: refreshPayload.role,
      permissions: refreshPayload.permissions,
      tokenType: 'access',
      vncSessionId: refreshPayload.vncSessionId,
      clientIp: refreshPayload.clientIp,
      computerUsePermissions: refreshPayload.computerUsePermissions,
      screenAccessLevel: refreshPayload.screenAccessLevel,
    };

    return this.jwtService.signAsync(accessPayload, {
      expiresIn: process.env.JWT_ACCESS_EXPIRY || '15m',
      issuer: 'bytebotd-enhanced',
      audience: 'computer-control',
    });
  }

  /**
   * Perform enhanced security checks beyond basic JWT validation
   */
  private async performEnhancedSecurityChecks(
    request: Request,
    operationId: string,
  ): Promise<{ passed: boolean; reason?: string }> {
    // Check for service-to-service authentication tokens
    const serviceToken = request.headers['x-service-token'] as string;
    if (
      serviceToken &&
      !(await this.validateServiceToken(serviceToken, operationId))
    ) {
      return { passed: false, reason: 'Invalid service authentication token' };
    }

    // Validate cross-origin requests for computer control
    if (
      request.method !== 'GET' &&
      !this.validateCorsForComputerControl(request)
    ) {
      return {
        passed: false,
        reason: 'CORS validation failed for computer control operation',
      };
    }

    // Check for suspicious request patterns
    if (this.detectSuspiciousPatterns(request)) {
      return { passed: false, reason: 'Suspicious request pattern detected' };
    }

    // Validate request size for computer control operations
    const contentLength = parseInt(request.headers['content-length'] || '0');
    if (contentLength > 10 * 1024 * 1024) {
      // 10MB limit
      return {
        passed: false,
        reason: 'Request payload too large for computer control',
      };
    }

    return { passed: true };
  }

  /**
   * Validate service-to-service authentication token
   */
  private async validateServiceToken(
    token: string,
    operationId: string,
  ): Promise<boolean> {
    // Check cache first for performance
    const cached = this.serviceAuthCache.get(token);
    if (cached && cached.expires > Date.now()) {
      return cached.valid;
    }

    try {
      const payload = await this.jwtService.verifyAsync<EnhancedJwtPayload>(
        token,
        {
          secret: process.env.SERVICE_JWT_SECRET || process.env.JWT_SECRET,
          audience: 'service-to-service',
        },
      );

      const isValid = !!(
        payload.tokenType === 'service' &&
        payload.serviceId &&
        payload.serviceType
      );

      // Cache result for 5 minutes
      this.serviceAuthCache.set(token, {
        valid: isValid,
        expires: Date.now() + 5 * 60 * 1000,
      });

      if (isValid) {
        this.logger.debug(`[${operationId}] Service authentication validated`, {
          operationId,
          serviceId: payload.serviceId,
          serviceType: payload.serviceType,
        });
      }

      return isValid;
    } catch (_error) {
      this.logger.warn(`[${operationId}] Service token validation failed`, {
        operationId,
        error: _error instanceof Error ? _error.message : String(_error),
      });

      // Cache negative result for 1 minute
      this.serviceAuthCache.set(token, {
        valid: false,
        expires: Date.now() + 60 * 1000,
      });

      return false;
    }
  }

  /**
   * Validate CORS for computer control operations
   */
  private validateCorsForComputerControl(request: Request): boolean {
    const origin = request.headers.origin;
    const allowedOrigins = process.env.COMPUTER_CONTROL_ALLOWED_ORIGINS?.split(
      ',',
    ) || [
      'http://localhost:3000',
      'http://localhost:3001',
      'https://app.bytebot.ai',
    ];

    // Allow same-origin requests
    if (!origin) {
      return true;
    }

    // Check against allowed origins
    return allowedOrigins.includes(origin);
  }

  /**
   * Detect suspicious request patterns
   */
  private detectSuspiciousPatterns(request: Request): boolean {
    const userAgent = request.headers['user-agent'] || '';
    const path = request.url;

    // Check for automation tools that shouldn't be used for computer control
    const suspiciousUserAgents = [
      /selenium/gi,
      /playwright/gi,
      /puppeteer/gi,
      /headless/gi,
      /bot/gi,
      /crawler/gi,
    ];

    if (suspiciousUserAgents.some((pattern) => pattern.test(userAgent))) {
      return true;
    }

    // Check for suspicious path patterns
    if (path.includes('../') || path.includes('..\\')) {
      return true;
    }

    // Check for SQL injection patterns in query strings
    const queryString = request.url.split('?')[1] || '';
    const sqlPatterns = [
      /union\s+select/gi,
      /drop\s+table/gi,
      /insert\s+into/gi,
      /delete\s+from/gi,
    ];

    if (sqlPatterns.some((pattern) => pattern.test(queryString))) {
      return true;
    }

    return false;
  }

  /**
   * Perform post-authentication validation with enhanced checks
   */
  private async performPostAuthValidation(
    request: EnhancedAuthenticatedRequest,
    operationId: string,
  ): Promise<void> {
    const user = request.user;

    // Check if user has minimum required role for computer control
    const requiredRoles: UserRole[] = [UserRole._ADMIN, UserRole._OPERATOR];
    if (!requiredRoles.includes(user.role)) {
      throw new ForbiddenException(
        'Insufficient role for computer control access',
      );
    }

    // Validate session consistency if available
    const sessionId = request.headers['x-session-id'] as string;
    if (sessionId && !this.validateSessionConsistency(user.id, sessionId)) {
      throw new UnauthorizedException('Session consistency validation failed');
    }

    // Check for concurrent session limits
    if (await this.exceedsConcurrentSessionLimit(user.id)) {
      throw new ForbiddenException('Maximum concurrent sessions exceeded');
    }

    this.logger.debug(
      `[${operationId}] Post-authentication validation passed`,
      {
        operationId,
        userId: user.id,
        role: user.role,
      },
    );
  }

  /**
   * Validate computer use permissions for specific operations
   */
  private async validateComputerUsePermissions(
    request: EnhancedAuthenticatedRequest,
    operationId: string,
  ): Promise<void> {
    const path = request.url.toLowerCase();
    let requiredPermissions = ComputerUsePermission.NONE;

    // Determine required permissions based on endpoint
    if (path.includes('/screenshot') || path.includes('/screen')) {
      requiredPermissions |= ComputerUsePermission.VIEW_SCREEN;
    }

    if (path.includes('/mouse') || path.includes('/click')) {
      requiredPermissions |= ComputerUsePermission.MOUSE_CONTROL;
    }

    if (path.includes('/keyboard') || path.includes('/type')) {
      requiredPermissions |= ComputerUsePermission.KEYBOARD_CONTROL;
    }

    if (path.includes('/file') || path.includes('/upload')) {
      requiredPermissions |= ComputerUsePermission.FILE_ACCESS;
    }

    if (path.includes('/clipboard')) {
      requiredPermissions |= ComputerUsePermission.CLIPBOARD_ACCESS;
    }

    if (path.includes('/vnc')) {
      requiredPermissions |= ComputerUsePermission.VNC_CONNECTION;
    }

    // For ADMIN users, grant full permissions
    if (request.user.role === UserRole._ADMIN) {
      request.securityContext.screenAccessGranted = true;
      return;
    }

    // TODO: In a real implementation, get user's computer use permissions from database
    // For now, grant view and basic control permissions to OPERATOR role
    const userPermissions =
      request.user.role === UserRole._OPERATOR
        ? ComputerUsePermission.VIEW_SCREEN |
          ComputerUsePermission.MOUSE_CONTROL |
          ComputerUsePermission.KEYBOARD_CONTROL
        : ComputerUsePermission.NONE;

    if ((userPermissions & requiredPermissions) !== requiredPermissions) {
      throw new ForbiddenException(
        'Insufficient computer use permissions for this operation',
      );
    }

    request.securityContext.screenAccessGranted = true;

    this.logger.debug(`[${operationId}] Computer use permissions validated`, {
      operationId,
      userId: request.user.id,
      requiredPermissions,
      userPermissions,
      granted: true,
    });
  }

  /**
   * Validate VNC session if applicable
   */
  private async validateVncSession(
    request: EnhancedAuthenticatedRequest,
    operationId: string,
  ): Promise<void> {
    const vncSessionId = request.headers['x-vnc-session'] as string;

    if (!vncSessionId) {
      // VNC session not required for all operations
      return;
    }

    // TODO: In a real implementation, validate VNC session against database
    // For now, perform basic format validation
    if (!/^vnc_[a-zA-Z0-9]{16,32}$/.test(vncSessionId)) {
      throw new BadRequestException('Invalid VNC session identifier format');
    }

    request.securityContext.vncSessionValid = true;

    this.logger.debug(`[${operationId}] VNC session validated`, {
      operationId,
      userId: request.user.id,
      vncSessionId,
    });
  }

  /**
   * Calculate risk score based on request context
   */
  private calculateRiskScore(request: EnhancedAuthenticatedRequest): number {
    let riskScore = 0;

    // Base risk for computer control operations
    riskScore += 30;

    // Increase risk for token refresh
    if (request.securityContext.tokenRefreshed) {
      riskScore += 15;
    }

    // Decrease risk for service authentication
    if (request.securityContext.serviceAuthentication) {
      riskScore -= 10;
    }

    // Increase risk for admin operations
    if (request.user.role === UserRole._ADMIN) {
      riskScore += 20;
    }

    // Increase risk based on endpoint sensitivity
    const path = request.url.toLowerCase();
    if (path.includes('/file') || path.includes('/upload')) {
      riskScore += 25;
    }

    if (path.includes('/vnc')) {
      riskScore += 30;
    }

    return Math.min(100, Math.max(0, riskScore));
  }

  /**
   * Validate session consistency
   */
  private validateSessionConsistency(
    userId: string,
    sessionId: string,
  ): boolean {
    // TODO: In a real implementation, validate against session store
    // For now, perform basic format validation
    return /^session_[a-zA-Z0-9]{16,32}$/.test(sessionId);
  }

  /**
   * Check if user exceeds concurrent session limit
   */
  private async exceedsConcurrentSessionLimit(
    _userId: string,
  ): Promise<boolean> {
    // TODO: In a real implementation, check against session store
    // For now, assume limit is not exceeded
    return false;
  }

  /**
   * Get client IP address with enhanced detection
   */
  private getClientIpAddress(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
      (request.headers['x-real-ip'] as string) ||
      (request.headers['x-client-ip'] as string) ||
      request.connection?.remoteAddress ||
      request.socket?.remoteAddress ||
      'unknown'
    );
  }

  /**
   * Clean up expired cache entries
   */
  private cleanupCaches(): void {
    const now = Date.now();

    // Clean up refresh attempts (older than 15 minutes)
    const _fifteenMinutesAgo = now - 15 * 60 * 1000;

    // Clean up service auth cache (expired entries)
    for (const [token, entry] of Array.from(this.serviceAuthCache.entries())) {
      if (entry.expires < now) {
        this.serviceAuthCache.delete(token);
      }
    }

    this.logger.debug('Cache cleanup completed', {
      serviceAuthCacheSize: this.serviceAuthCache.size,
      refreshAttemptsSize: this.refreshAttempts.size,
    });
  }

  /**
   * Handle authentication request with enhanced error information
   */
  handleRequest<TUser = any>(
    err: any,
    user: any,
    info: any,
    context: ExecutionContext,
  ): TUser {
    const operationId = `enhanced-jwt-handle-${Date.now()}`;
    const request = context
      .switchToHttp()
      .getRequest<EnhancedAuthenticatedRequest>();

    if (err) {
      this.logger.error(`[${operationId}] Enhanced authentication error`, {
        operationId,
        error: err instanceof Error ? err.message : String(err),
        stack: err instanceof Error ? err.stack : undefined,
        url: request.url,
        method: request.method,
        securityEvent: 'enhanced_auth_error',
      });
      throw new UnauthorizedException('Enhanced authentication failed');
    }

    if (!user) {
      const errorMessage = this.getEnhancedAuthErrorMessage(info);

      this.logger.warn(
        `[${operationId}] Enhanced authentication failed - no user`,
        {
          operationId,
          info: info?.message || info?.name || String(info),
          url: request.url,
          method: request.method,
          errorMessage,
          securityEvent: 'enhanced_auth_no_user',
        },
      );

      throw new UnauthorizedException(errorMessage);
    }

    this.logger.debug(
      `[${operationId}] Enhanced authentication request handled successfully`,
      {
        operationId,
        userId: user.id,
        username: user.username,
        role: user.role,
        url: request.url,
        method: request.method,
      },
    );

    return user;
  }

  /**
   * Get enhanced authentication error message
   */
  private getEnhancedAuthErrorMessage(info: any): string {
    if (!info) {
      return 'Enhanced authentication required for computer control';
    }

    const message = info.message || info.name || String(info);

    switch (message) {
      case 'TokenExpiredError':
      case 'jwt expired':
        return 'Access token has expired - refresh required';

      case 'JsonWebTokenError':
      case 'invalid token':
        return 'Invalid access token format';

      case 'NotBeforeError':
        return 'Token not yet valid';

      case 'No auth token':
        return 'Access token required for computer control operations';

      default:
        return 'Enhanced authentication failed for computer control';
    }
  }
}

/**
 * JWT Authentication Guard - ByteBotd Computer Control Service
 * Protects computer automation endpoints with JWT token validation
 *
 * Features:
 * - JWT token validation with automatic user extraction
 * - Comprehensive security logging for computer control access
 * - Request context enhancement with authenticated user
 * - Graceful error handling for authentication failures
 * - Integration with shared security types
 *
 * @author Security Implementation Specialist
 * @version 1.0.0
 * @since ByteBotd Authentication Hardening
 */

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
  Logger,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { Request } from 'express';
import { UserRole } from '@bytebot/shared';

/**
 * User interface for ByteBotd (subset of full User model)
 */
export interface ByteBotdUser {
  id: string;
  email: string;
  username: string;
  firstName?: string;
  lastName?: string;
  role: UserRole;
  isActive: boolean;
}

/**
 * Extended Request interface with authenticated user
 */
export interface AuthenticatedRequest extends Request {
  user: ByteBotdUser;
}

/**
 * JWT Authentication Guard for ByteBotd
 * Validates JWT tokens and protects computer control routes
 */
@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  private readonly logger = new Logger(JwtAuthGuard.name);

  constructor(private readonly reflector: Reflector) {
    super();
  }

  /**
   * Enhanced JWT validation with comprehensive security checks
   * Validates JWT token, extracts authenticated user, and performs additional security validations
   *
   * @param context - Execution context containing request information
   * @returns Promise<boolean> - Whether the request is authorized
   * @throws UnauthorizedException - When authentication fails
   */
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const operationId = `bytebotd-jwt-auth-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`;
    const startTime = Date.now();

    // Check if route is marked as public (skip authentication)
    const isPublic = this.reflector.getAllAndOverride<boolean>('isPublic', [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      this.logger.debug(
        `[${operationId}] Route marked as public, skipping authentication`,
        {
          operationId,
          route: this.getRouteInfo(context),
        },
      );
      return true;
    }

    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const clientIp = this.getClientIpAddress(request);
    const userAgent = request.headers['user-agent']?.substring(0, 100);

    // Enhanced security logging with threat detection
    this.logger.debug(
      `[${operationId}] Enhanced JWT authentication attempt for computer control`,
      {
        operationId,
        method: request.method,
        url: request.url,
        userAgent,
        ipAddress: clientIp,
        timestamp: new Date().toISOString(),
        securityContext: 'computer_control_access',
      },
    );

    // Pre-authentication security checks
    if (!this.performPreAuthChecks(request, operationId)) {
      throw new UnauthorizedException(
        'Pre-authentication security check failed',
      );
    }

    try {
      // Call parent authentication logic (Passport JWT strategy)
      const _result = await super.canActivate(context); // Note: const reassignment issue fixed

      if (_result) {
        const authTime = Date.now() - startTime;
        const user = request.user;

        // Perform post-authentication security checks
        if (user && !this.performPostAuthChecks(user, operationId)) {
          throw new UnauthorizedException(
            'Post-authentication security check failed',
          );
        }

        this.logger.log(
          `[${operationId}] Enhanced JWT authentication successful for computer control`,
          {
            operationId,
            userId: user?.id,
            username: user?.username,
            role: user?.role,
            method: request.method,
            url: request.url,
            authTimeMs: authTime,
            ipAddress: clientIp,
            userAgent,
            securityLevel: 'enhanced',
            securityEvent: 'computer_control_auth_success',
            postAuthChecks: 'passed',
          },
        );
      }

      return _result as boolean;
    } catch (_error) {
      const authTime = Date.now() - startTime;

      // Log authentication failure with enhanced security context
      this.logger.warn(
        `[${operationId}] JWT authentication failed for computer control access`,
        {
          operationId,
          method: request.method,
          url: request.url,
          error: _error instanceof Error ? _error.message : String(_error),
          authTimeMs: authTime,
          ipAddress: this.getClientIpAddress(request),
          userAgent: request.headers['user-agent']?.substring(0, 100),
          hasAuthHeader: !!request.headers.authorization,
          authHeaderFormat: this.analyzeAuthHeader(
            request.headers.authorization,
          ),
          securityEvent: 'computer_control_auth_failed',
          riskScore: 85, // High risk for computer control access attempts
        },
      );

      // Re-throw as UnauthorizedException for consistent error handling
      if (_error instanceof UnauthorizedException) {
        throw _error;
      }

      throw new UnauthorizedException(
        'Authentication required for computer control',
      );
    }
  }

  /**
   * Handle authentication request and provide detailed error information
   * Called by Passport strategy when authentication fails
   *
   * @param err - Authentication error
   * @param user - Authenticated user (if successful)
   * @param info - Additional authentication information
   * @param context - Execution context
   * @returns User object or throws UnauthorizedException
   */
  handleRequest<TUser = any>(
    err: unknown,
    user: unknown,
    info: unknown,
    context: ExecutionContext,
  ): TUser {
    const operationId = `bytebotd-jwt-handle-${Date.now()}`;
    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();

    // Handle authentication errors
    if (err) {
      this.logger.error(
        `[${operationId}] Computer control authentication error`,
        {
          operationId,
          _error: err instanceof Error ? err.message : String(err),
          stack: err instanceof Error ? err.stack : undefined,
          url: request.url,
          method: request.method,
          ipAddress: this.getClientIpAddress(request),
          securityEvent: 'computer_control_auth_error',
        },
      );
      throw new UnauthorizedException(
        'Authentication failed for computer control',
      );
    }

    // Handle missing or invalid user
    if (!user) {
      const errorMessage = this.getAuthErrorMessage(info);

      this.logger.warn(
        `[${operationId}] Computer control authentication failed - no user`,
        {
          operationId,
          info: (info as any)?.message || (info as any)?.name || String(info),
          url: request.url,
          method: request.method,
          ipAddress: this.getClientIpAddress(request),
          errorMessage,
          securityEvent: 'computer_control_no_user',
        },
      );

      throw new UnauthorizedException(errorMessage);
    }

    // Successful authentication
    this.logger.debug(
      `[${operationId}] Computer control authentication request handled successfully`,
      {
        operationId,
        userId: (user as ByteBotdUser).id,
        username: (user as ByteBotdUser).username,
        role: (user as ByteBotdUser).role,
        url: request.url,
        method: request.method,
        securityEvent: 'computer_control_auth_handled',
      },
    );

    return user as TUser;
  }

  /**
   * Extract client IP address from request
   * Handles various proxy configurations and headers
   *
   * @param request - HTTP request object
   * @returns string - Client IP address
   * @private
   */
  private getClientIpAddress(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
      (request.headers['x-real-ip'] as string) ||
      request.connection?.remoteAddress ||
      request.socket?.remoteAddress ||
      'unknown'
    );
  }

  /**
   * Get route information for logging
   * Extracts handler and controller information
   *
   * @param context - Execution context
   * @returns string - Route identifier
   * @private
   */
  private getRouteInfo(context: ExecutionContext): string {
    const handler = context.getHandler().name;
    const controller = context.getClass().name;
    return `${controller}.${handler}`;
  }

  /**
   * Analyze Authorization header format for debugging
   * Helps identify common authentication issues
   *
   * @param authHeader - Authorization header value
   * @returns string - Analysis result
   * @private
   */
  private analyzeAuthHeader(authHeader?: string): string {
    if (!authHeader) {
      return 'missing';
    }

    if (!authHeader.startsWith('Bearer ')) {
      return `invalid-format-${authHeader.split(' ')[0] || 'no-type'}`;
    }

    const token = authHeader.substring(7);
    if (!token) {
      return 'missing-token';
    }

    // Basic JWT format validation
    const parts = token.split('.');
    if (parts.length !== 3) {
      return `invalid-jwt-parts-${parts.length}`;
    }

    return 'valid-format';
  }

  /**
   * Get user-friendly authentication error message
   * Provides clear error messages for common authentication failures
   *
   * @param info - Passport authentication info object
   * @returns string - User-friendly error message
   * @private
   */
  private getAuthErrorMessage(info: unknown): string {
    if (!info) {
      return 'Authentication required for computer control';
    }

    const message =
      (info as any)?.message || (info as any)?.name || String(info);

    // Common JWT errors with user-friendly messages
    switch (message) {
      case 'TokenExpiredError':
      case 'jwt expired':
        return 'Access token has expired';

      case 'JsonWebTokenError':
      case 'invalid token':
        return 'Invalid access token';

      case 'NotBeforeError':
        return 'Token not active yet';

      case 'No auth token':
        return 'Access token required for computer control';

      default:
        return 'Authentication failed for computer control';
    }
  }

  /**
   * Enhanced pre-authentication security checks
   * Validates request headers, IP patterns, and potential security threats
   *
   * @param request - HTTP request object
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether pre-auth checks passed
   * @private
   */
  private performPreAuthChecks(request: Request, operationId: string): boolean {
    // Check for suspicious user agent patterns
    const userAgent = request.headers['user-agent'];
    if (!userAgent || this.isSuspiciousUserAgent(userAgent)) {
      this.logger.warn(`[${operationId}] Suspicious user agent detected`, {
        operationId,
        userAgent,
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'suspicious_user_agent',
      });
      return false;
    }

    // Check for excessive header count (potential attack)
    const headerCount = Object.keys(request.headers).length;
    if (headerCount > 50) {
      this.logger.warn(`[${operationId}] Excessive headers detected`, {
        operationId,
        headerCount,
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'excessive_headers',
      });
      return false;
    }

    // Validate Authorization header format
    const authHeader = request.headers.authorization;
    if (authHeader && !this.isValidAuthHeaderFormat(authHeader)) {
      this.logger.warn(`[${operationId}] Invalid authorization header format`, {
        operationId,
        authHeaderFormat: this.analyzeAuthHeader(authHeader),
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'invalid_auth_header',
      });
      return false;
    }

    // Check for potential token replay attacks (basic timing check)
    if (authHeader && this.isPotentialReplayAttack(authHeader, operationId)) {
      this.logger.warn(
        `[${operationId}] Potential token replay attack detected`,
        {
          operationId,
          ipAddress: this.getClientIpAddress(request),
          securityEvent: 'potential_replay_attack',
        },
      );
      return false;
    }

    return true;
  }

  /**
   * Check if user agent indicates suspicious activity
   * Detects bots, scrapers, and automated tools
   *
   * @param userAgent - User agent string
   * @returns boolean - Whether user agent is suspicious
   * @private
   */
  private isSuspiciousUserAgent(userAgent: string): boolean {
    const suspiciousPatterns = [
      // Common bots and scrapers
      /bot|crawler|spider|scraper/gi,

      // Automated tools
      /curl|wget|httpie|postman|insomnia/gi,

      // Security scanners
      /nmap|nikto|sqlmap|burp|zap|acunetix|nessus/gi,

      // Generic HTTP clients
      /^(python|java|go|rust|php|ruby|perl)-/gi,

      // Empty or very short user agents
      /^.{0,10}$/,

      // Common attack tools
      /metasploit|exploit|payload|shell/gi,
    ];

    return suspiciousPatterns.some((pattern) => pattern.test(userAgent));
  }

  /**
   * Validate authorization header format
   * Ensures proper Bearer token format
   *
   * @param authHeader - Authorization header value
   * @returns boolean - Whether format is valid
   * @private
   */
  private isValidAuthHeaderFormat(authHeader: string): boolean {
    // Must be Bearer token format
    if (!authHeader.startsWith('Bearer ')) {
      return false;
    }

    const token = authHeader.substring(7);

    // Token must exist and be reasonable length
    if (!token || token.length < 20 || token.length > 2048) {
      return false;
    }

    // Basic JWT format check (3 parts separated by dots)
    const parts = token.split('.');
    if (parts.length !== 3) {
      return false;
    }

    // Each part should be base64url encoded (basic check)
    return parts.every(
      (part) => /^[A-Za-z0-9_-]+$/.test(part) && part.length > 0,
    );
  }

  /**
   * Basic replay attack detection using timing analysis
   * This is a simplified approach - production systems should use nonces
   *
   * @param authHeader - Authorization header value
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether this might be a replay attack
   * @private
   */
  private isPotentialReplayAttack(
    authHeader: string,
    operationId: string,
  ): boolean {
    try {
      const token = authHeader.substring(7);
      const tokenParts = token.split('.');

      if (tokenParts.length !== 3) {
        return false;
      }

      // Decode JWT payload (without verification - just for timing check)
      // Convert base64url to base64 and decode
      const payloadPart = tokenParts[1];
      if (!payloadPart) {
        return false;
      }
      const base64Payload = payloadPart.replace(/-/g, '+').replace(/_/g, '/');
      const payload = JSON.parse(
        Buffer.from(base64Payload, 'base64').toString('utf8'),
      );

      const currentTime = Math.floor(Date.now() / 1000);
      const tokenIssuedAt = payload.iat;
      const tokenExpiry = payload.exp;

      // Check if token is very close to expiry (potential replay)
      if (tokenExpiry && currentTime > tokenExpiry - 60) {
        return true;
      }

      // Check if token was issued very recently (less than 1 second ago)
      // This could indicate rapid successive requests with the same token
      if (tokenIssuedAt && currentTime - tokenIssuedAt < 1) {
        return true;
      }
    } catch (_error) {
      // If we can't decode the token, let the main JWT validation handle it
      this.logger.debug(
        `[${operationId}] Could not decode JWT for replay check: ${_error instanceof Error ? _error.message : String(_error)}`,
      );
    }

    return false;
  }

  /**
   * Enhanced post-authentication user validation
   * Performs additional security checks on authenticated user
   *
   * @param user - Authenticated user object
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether user passed additional security checks
   * @private
   */
  private performPostAuthChecks(
    user: ByteBotdUser,
    operationId: string,
  ): boolean {
    // Check if user account is active
    if (!user.isActive) {
      this.logger.warn(`[${operationId}] Inactive user attempted access`, {
        operationId,
        userId: user.id,
        username: user.username,
        securityEvent: 'inactive_user_access',
      });
      return false;
    }

    // Check user role permissions for computer control
    const allowedRoles: UserRole[] = [UserRole._ADMIN, UserRole._OPERATOR];
    if (!allowedRoles.includes(user.role)) {
      this.logger.warn(
        `[${operationId}] Unauthorized role attempted computer control access`,
        {
          operationId,
          userId: user.id,
          username: user.username,
          role: user.role,
          securityEvent: 'unauthorized_role_access',
        },
      );
      return false;
    }

    // Additional security validations can be added here
    // - Account lockout checks
    // - Concurrent session limits
    // - Geographic location validation
    // - Time-based access controls

    return true;
  }
}

/**
 * JWT Strategy - ByteBotd JWT Token Validation
 * Implements Passport JWT strategy for computer control authentication
 *
 * Features:
 * - JWT token validation with shared secret
 * - User payload extraction and validation
 * - Integration with shared security types
 * - Computer control specific security context
 *
 * @author Security Implementation Specialist
 * @version 1.0.0
 * @since ByteBotd Authentication Hardening
 */

import { Injectable, UnauthorizedException, Logger } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UserRole } from '@bytebot/shared';
import { ByteBotdUser } from '../guards/jwt-auth.guard';

/**
 * JWT payload interface for ByteBotd authentication
 */
interface JwtPayload {
  sub: string; // User ID
  email: string;
  username: string;
  firstName?: string;
  lastName?: string;
  role: UserRole;
  isActive: boolean;
  iat: number; // Issued at
  exp: number; // Expires at
}

/**
 * JWT Strategy for ByteBotd computer control authentication
 * Validates JWT tokens and extracts user information
 */
@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  private readonly logger = new Logger(JwtStrategy.name);

  constructor() {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey:
        process.env.JWT_SECRET || 'bytebot-default-secret-change-in-production',
      algorithms: ['HS256'],
    });
  }

  /**
   * Validate JWT payload and extract user information
   * Called by Passport JWT strategy after token validation
   *
   * @param payload - Validated JWT payload
   * @returns Promise<ByteBotdUser> - User object for request context
   * @throws UnauthorizedException - When user is invalid or inactive
   */
  async validate(payload: JwtPayload): Promise<ByteBotdUser> {
    const operationId = `bytebotd-jwt-validate-${Date.now()}`;

    this.logger.debug(
      `[${operationId}] JWT payload validation for computer control`,
      {
        operationId,
        userId: payload.sub,
        username: payload.username,
        role: payload.role,
        isActive: payload.isActive,
        tokenIssuedAt: new Date(payload.iat * 1000),
        tokenExpiresAt: new Date(payload.exp * 1000),
        securityEvent: 'computer_control_jwt_validation',
      },
    );

    // Validate required payload fields
    if (!payload.sub || !payload.email || !payload.username || !payload.role) {
      this.logger.warn(
        `[${operationId}] Invalid JWT payload - missing required fields`,
        {
          operationId,
          userId: payload.sub,
          hasEmail: !!payload.email,
          hasUsername: !!payload.username,
          hasRole: !!payload.role,
          securityEvent: 'computer_control_invalid_jwt_payload',
        },
      );
      throw new UnauthorizedException('Invalid token payload');
    }

    // Check if user is active
    if (!payload.isActive) {
      this.logger.warn(
        `[${operationId}] Inactive user attempting computer control access`,
        {
          operationId,
          userId: payload.sub,
          username: payload.username,
          role: payload.role,
          securityEvent: 'computer_control_inactive_user_access',
          riskScore: 75,
        },
      );
      throw new UnauthorizedException('Account is inactive');
    }

    // Create user object for request context
    const user: ByteBotdUser = {
      id: payload.sub,
      email: payload.email,
      username: payload.username,
      firstName: payload.firstName,
      lastName: payload.lastName,
      role: payload.role,
      isActive: payload.isActive,
    };

    this.logger.debug(
      `[${operationId}] JWT validation successful for computer control`,
      {
        operationId,
        userId: user.id,
        username: user.username,
        role: user.role,
        securityEvent: 'computer_control_jwt_validated',
      },
    );

    return user;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import { BrowserUseService } from './browser-use.service';
import { BrowserTaskService } from './browser-task.service';
import {
  CreateAsyncJobDto,
  AsyncJobResultDto,
  AsyncJobStatus,
  AsyncJobType,
  AsyncJobPriority,
} from './dto/async-job.dto';
import {
  CreateBrowserTaskDto as _CreateBrowserTaskDto,
  BrowserTaskStatus as _BrowserTaskStatus,
} from './dto/browser-task.dto';

/**
 * Browser Async Job Service - Long-Running Task Management
 *
 * Manages asynchronous browser automation jobs that may take extended time to complete.
 * Provides queue management, progress monitoring, and resource optimization for
 * complex browser automation workflows.
 *
 * Key Responsibilities:
 * - Async job lifecycle management
 * - Queue processing and prioritization
 * - Progress monitoring and reporting
 * - Resource allocation and cleanup
 * - Batch processing coordination
 * - Error recovery and retry logic
 */
@Injectable()
export class BrowserAsyncJobService {
  private readonly logger = new Logger(BrowserAsyncJobService.name);
  private readonly jobs: Map<string, AsyncJobResultDto> = new Map();
  private readonly jobQueue: string[] = [];
  private readonly processingJobs = new Set<string>();
  private readonly maxConcurrentJobs = 3;
  private readonly jobProcessingInterval: NodeJS.Timeout;

  constructor(
    private readonly browserService: BrowserUseService,
    private readonly taskService: BrowserTaskService,
  ) {
    // Start job processor
    this.jobProcessingInterval = setInterval(() => {
      this.processJobQueue().catch((err) => {
        this.logger.error('Job queue processing failed', err);
      });
    }, 5000); // Check every 5 seconds

    this.logger.log('Browser Async Job Service initialized');
  }

  /**
   * Create a new async job
   */
  async createAsyncJob(_dto: CreateAsyncJobDto): Promise<AsyncJobResultDto> {
    const jobId = uuidv4();
    const now = new Date();

    this.logger.log(`Creating async job: ${_dto.name}`, {
      jobId,
      name: _dto.name,
      jobType: _dto.jobType,
      priority: _dto.priority,
      estimatedDurationMs: _dto.estimatedDurationMs,
    });

    try {
      const job: AsyncJobResultDto = {
        jobId,
        name: _dto.name,
        description: _dto.description,
        jobType: _dto.jobType,
        status: AsyncJobStatus.QUEUED,
        priority: _dto.priority || AsyncJobPriority.NORMAL,
        progress: {
          currentStep: 'Job queued for processing',
          completedSteps: 0,
          totalSteps: this.estimateTotalSteps(_dto),
          percentage: 0,
          estimatedRemainingMs: _dto.estimatedDurationMs || 300000,
        },
        createdAt: now,
        queuedAt: now,
        estimatedDurationMs: _dto.estimatedDurationMs || 300000,
        configuration: _dto.configuration,
        results: {
          tasksCompleted: 0,
          totalTasks: 0,
          screenshots: [],
          extractedData: {},
          logs: [],
        },
        metadata: {
          retryCount: 0,
          maxRetries: _dto.maxRetries || 3,
          createdBy: 'browser-automation-api',
          tags: _dto.tags || [],
          ..._dto.metadata,
        },
      };

      // Store job
      this.jobs.set(jobId, job);

      // Add to priority queue
      this.addToQueue(jobId);

      this.logger.log(`Async job created and queued: ${jobId}`, {
        jobId,
        status: job.status,
        queuePosition: this.getQueuePosition(jobId),
      });

      return job;
    } catch (_err) {
      this.logger.error(`Failed to create async job: ${_dto.name}`, _err);
      throw _err;
    }
  }

  /**
   * Get async job by ID
   */
  async getAsyncJob(jobId: string): Promise<AsyncJobResultDto | null> {
    const job = this.jobs.get(jobId);

    if (!job) {
      return null;
    }

    // Update progress for running jobs
    if (job.status === AsyncJobStatus.RUNNING) {
      await this.updateJobProgress(jobId);
    }

    return job;
  }

  /**
   * Get all async jobs
   */
  async getAllAsyncJobs(): Promise<AsyncJobResultDto[]> {
    const jobs = Array.from(this.jobs.values());

    // Update progress for running jobs
    const runningJobs = jobs.filter(
      (job) => job.status === AsyncJobStatus.RUNNING,
    );
    for (const job of runningJobs) {
      await this.updateJobProgress(job.jobId);
    }

    return jobs;
  }

  /**
   * Cancel async job
   */
  async cancelAsyncJob(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      throw new Error(`Async job not found: ${jobId}`);
    }

    if (
      job.status === AsyncJobStatus.COMPLETED ||
      job.status === AsyncJobStatus.FAILED ||
      job.status === AsyncJobStatus.CANCELLED
    ) {
      throw new Error(`Cannot cancel job in status: ${job.status}`);
    }

    this.logger.log(`Cancelling async job: ${jobId}`, {
      jobId,
      currentStatus: job.status,
    });

    // Store the current status before updating
    const wasRunning = job.status === AsyncJobStatus.RUNNING;

    // Update job status
    job.status = AsyncJobStatus.CANCELLED;
    job.completedAt = new Date();
    job.progress.currentStep = 'Job cancelled by user';

    // Add cancellation log
    job.results.logs.push({
      timestamp: new Date(),
      level: 'warn',
      message: 'Async job cancelled by user',
      metadata: {
        reason: 'user_cancellation',
        completedSteps: job.progress.completedSteps,
        totalSteps: job.progress.totalSteps,
      },
    });

    // Remove from queue if not yet started
    const queueIndex = this.jobQueue.indexOf(jobId);
    if (queueIndex >= 0) {
      this.jobQueue.splice(queueIndex, 1);
    }

    // Cancel associated tasks if was running
    if (wasRunning && job.taskIds) {
      for (const taskId of job.taskIds) {
        try {
          await this.taskService.cancelTask(taskId);
        } catch (_err) {
          this.logger.warn(`Failed to cancel associated task: ${taskId}`, _err);
        }
      }
    }

    // Remove from processing set
    this.processingJobs.delete(jobId);

    this.jobs.set(jobId, job);

    this.logger.log(`Async job cancelled: ${jobId}`, {
      jobId,
      completedSteps: job.progress.completedSteps,
      totalSteps: job.progress.totalSteps,
    });
  }

  /**
   * Delete completed job (cleanup)
   */
  async deleteAsyncJob(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Only allow deletion of completed, failed, or cancelled jobs
    if (
      job.status === AsyncJobStatus.RUNNING ||
      job.status === AsyncJobStatus.QUEUED
    ) {
      throw new Error(`Cannot delete job in status: ${job.status}`);
    }

    // Remove from queue if present
    const queueIndex = this.jobQueue.indexOf(jobId);
    if (queueIndex >= 0) {
      this.jobQueue.splice(queueIndex, 1);
    }

    // Delete associated tasks
    if (job.taskIds) {
      for (const taskId of job.taskIds) {
        try {
          await this.taskService.deleteTask(taskId);
        } catch (_err) {
          this.logger.warn(`Failed to delete associated task: ${taskId}`, _err);
        }
      }
    }

    // Delete job
    this.jobs.delete(jobId);

    this.logger.log(`Async job deleted: ${jobId}`, {
      jobId,
      status: job.status,
    });
  }

  /**
   * Get queue status and statistics
   */
  async getQueueStatus(): Promise<{
    queueLength: number;
    processingJobs: number;
    completedJobs: number;
    failedJobs: number;
    totalJobs: number;
    averageProcessingTime: number;
  }> {
    const jobs = Array.from(this.jobs.values());

    const completedJobs = jobs.filter(
      (j) => j.status === AsyncJobStatus.COMPLETED,
    );
    const failedJobs = jobs.filter((j) => j.status === AsyncJobStatus.FAILED);

    const totalProcessingTime = completedJobs.reduce((sum, job) => {
      if (job.startedAt && job.completedAt) {
        return sum + (job.completedAt.getTime() - job.startedAt.getTime());
      }
      return sum;
    }, 0);

    const averageProcessingTime =
      completedJobs.length > 0 ? totalProcessingTime / completedJobs.length : 0;

    return {
      queueLength: this.jobQueue.length,
      processingJobs: this.processingJobs.size,
      completedJobs: completedJobs.length,
      failedJobs: failedJobs.length,
      totalJobs: this.jobs.size,
      averageProcessingTime: Math.round(averageProcessingTime),
    };
  }

  /**
   * Clean up old jobs
   */
  async cleanupOldJobs(maxAge: number = 86400000): Promise<number> {
    // 24 hours default
    const now = Date.now();
    let cleanedCount = 0;

    for (const [jobId, job] of this.jobs.entries()) {
      // Skip active jobs
      if (
        job.status === AsyncJobStatus.RUNNING ||
        job.status === AsyncJobStatus.QUEUED
      ) {
        continue;
      }

      // Check age
      const jobAge = job.completedAt
        ? now - job.completedAt.getTime()
        : now - job.createdAt.getTime();

      if (jobAge > maxAge) {
        await this.deleteAsyncJob(jobId);
        cleanedCount++;
      }
    }

    if (cleanedCount > 0) {
      this.logger.log(`Cleaned up ${cleanedCount} old async jobs`, {
        cleanedCount,
        maxAgeHours: maxAge / (1000 * 60 * 60),
        remainingJobs: this.jobs.size,
      });
    }

    return cleanedCount;
  }

  // ===========================
  // PRIVATE METHODS
  // ===========================

  /**
   * Process job queue
   */
  private async processJobQueue(): Promise<void> {
    // Check if we can process more jobs
    if (this.processingJobs.size >= this.maxConcurrentJobs) {
      return;
    }

    // Get next job from queue
    const jobId = this.getNextJobFromQueue();
    if (!jobId) {
      return;
    }

    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Start processing job
    this.processingJobs.add(jobId);

    this.logger.log(`Starting async job processing: ${jobId}`, {
      jobId,
      jobType: job.jobType,
      priority: job.priority,
    });

    try {
      await this.processJob(job);
    } catch (_err) {
      this.logger.error(`Job processing failed: ${jobId}`, _err);
      await this.handleJobFailure(jobId, _err);
    } finally {
      this.processingJobs.delete(jobId);
    }
  }

  /**
   * Process individual job
   */
  private async processJob(job: AsyncJobResultDto): Promise<void> {
    // Update job status
    job.status = AsyncJobStatus.RUNNING;
    job.startedAt = new Date();
    job.progress.currentStep = 'Initializing job processing';

    this.jobs.set(job.jobId, job);

    switch (job.jobType) {
      case AsyncJobType.BATCH_AUTOMATION:
        await this.processBatchAutomation(job);
        break;

      case AsyncJobType.DATA_EXTRACTION:
        await this.processDataExtraction(job);
        break;

      case AsyncJobType.FORM_FILLING:
        await this.processFormFilling(job);
        break;

      case AsyncJobType.SCREENSHOT_CAPTURE:
        await this.processScreenshotCapture(job);
        break;

      case AsyncJobType.CUSTOM_WORKFLOW:
        await this.processCustomWorkflow(job);
        break;

      default:
        throw new Error(`Unsupported job type: ${job.jobType}`);
    }

    // Mark job as completed
    await this.completeJob(job);
  }

  /**
   * Process batch automation job
   */
  private async processBatchAutomation(job: AsyncJobResultDto): Promise<void> {
    const config = job.configuration;
    const tasks = config.tasks || [];

    job.progress.totalSteps = tasks.length;
    job.results.totalTasks = tasks.length;

    for (let i = 0; i < tasks.length; i++) {
      const taskConfig = tasks[i];

      job.progress.currentStep = `Processing task ${i + 1}/${tasks.length}: ${taskConfig.name}`;
      job.progress.completedSteps = i;
      job.progress.percentage = Math.round((i / tasks.length) * 100);

      this.jobs.set(job.jobId, job);

      try {
        const taskResult =
          await this.browserService.executeBrowserTask(taskConfig);

        // Store task ID for tracking
        if (!job.taskIds) {
          job.taskIds = [];
        }
        job.taskIds.push(taskResult.taskId);

        // Collect results
        if (taskResult.screenshots) {
          job.results.screenshots.push(...taskResult.screenshots);
        }

        if (taskResult.extractedData) {
          job.results.extractedData[`task_${i}`] = taskResult.extractedData;
        }

        job.results.tasksCompleted++;

        job.results.logs.push({
          timestamp: new Date(),
          level: 'info',
          message: `Task completed: ${taskConfig.name}`,
          metadata: {
            taskIndex: i,
            taskId: taskResult.taskId,
            status: taskResult.status,
          },
        });
      } catch (_err) {
        job.results.logs.push({
          timestamp: new Date(),
          level: 'error',
          message: `Task failed: ${taskConfig.name}`,
          metadata: {
            taskIndex: i,
            error: _err instanceof Error ? _err.message : String(_err),
          },
        });

        // Continue with next task unless configured to stop on error
        if (!config.continueOnError) {
          throw _err;
        }
      }
    }
  }

  /**
   * Process data extraction job
   */
  private async processDataExtraction(job: AsyncJobResultDto): Promise<void> {
    const config = job.configuration;
    const urls = config.urls || [];

    job.progress.totalSteps = urls.length;

    for (let i = 0; i < urls.length; i++) {
      const url = urls[i];

      job.progress.currentStep = `Extracting data from ${url}`;
      job.progress.completedSteps = i;
      job.progress.percentage = Math.round((i / urls.length) * 100);

      this.jobs.set(job.jobId, job);

      try {
        // Create session for data extraction
        const sessionId = await this.createExtractionSession();

        const extractedData = await this.browserService.extractPageData(
          sessionId,
          {
            selectors: config.selectors,
            waitForSelector: config.waitForSelector,
            timeout: config.timeout || 30000,
          },
        );

        job.results.extractedData[url] = extractedData;

        job.results.logs.push({
          timestamp: new Date(),
          level: 'info',
          message: `Data extracted from: ${url}`,
          metadata: {
            url,
            dataKeys: Object.keys(extractedData).length,
          },
        });
      } catch (_err) {
        job.results.logs.push({
          timestamp: new Date(),
          level: 'error',
          message: `Data extraction failed for: ${url}`,
          metadata: {
            url,
            error: _err instanceof Error ? _err.message : String(_err),
          },
        });

        if (!config.continueOnError) {
          throw _err;
        }
      }
    }
  }

  /**
   * Process other job types (placeholder implementations)
   */
  private async processFormFilling(job: AsyncJobResultDto): Promise<void> {
    // Implementation for form filling jobs
    job.progress.currentStep = 'Processing form filling job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  private async processScreenshotCapture(
    job: AsyncJobResultDto,
  ): Promise<void> {
    // Implementation for screenshot capture jobs
    job.progress.currentStep = 'Processing screenshot capture job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  private async processCustomWorkflow(job: AsyncJobResultDto): Promise<void> {
    // Implementation for custom workflow jobs
    job.progress.currentStep = 'Processing custom workflow job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  /**
   * Complete job processing
   */
  private async completeJob(job: AsyncJobResultDto): Promise<void> {
    job.status = AsyncJobStatus.COMPLETED;
    job.completedAt = new Date();
    job.progress.currentStep = 'Job completed successfully';
    job.progress.percentage = 100;

    if (job.startedAt) {
      job.actualDurationMs =
        job.completedAt.getTime() - job.startedAt.getTime();
    }

    job.results.logs.push({
      timestamp: new Date(),
      level: 'info',
      message: 'Async job completed successfully',
      metadata: {
        tasksCompleted: job.results.tasksCompleted,
        totalTasks: job.results.totalTasks,
        actualDurationMs: job.actualDurationMs,
      },
    });

    this.jobs.set(job.jobId, job);

    this.logger.log(`Async job completed: ${job.jobId}`, {
      jobId: job.jobId,
      actualDurationMs: job.actualDurationMs,
      tasksCompleted: job.results.tasksCompleted,
    });
  }

  /**
   * Handle job failure
   */
  private async handleJobFailure(jobId: string, error: any): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    job.status = AsyncJobStatus.FAILED;
    job.completedAt = new Date();
    job.errorMessage = error instanceof Error ? error.message : String(error);
    job.progress.currentStep = `Job failed: ${job.errorMessage}`;

    if (job.startedAt) {
      job.actualDurationMs =
        job.completedAt.getTime() - job.startedAt.getTime();
    }

    job.results.logs.push({
      timestamp: new Date(),
      level: 'error',
      message: 'Async job failed',
      metadata: {
        error: job.errorMessage,
        retryCount: job.metadata.retryCount,
        maxRetries: job.metadata.maxRetries,
      },
    });

    // Check if we should retry
    if (job.metadata.retryCount < job.metadata.maxRetries) {
      job.metadata.retryCount++;
      job.status = AsyncJobStatus.QUEUED;
      job.progress.currentStep = `Retrying job (attempt ${job.metadata.retryCount + 1}/${job.metadata.maxRetries + 1})`;

      // Add back to queue for retry
      this.addToQueue(jobId);

      this.logger.warn(`Job failed, retrying: ${jobId}`, {
        jobId,
        retryCount: job.metadata.retryCount,
        maxRetries: job.metadata.maxRetries,
      });
    } else {
      this.logger.error(`Job failed permanently: ${jobId}`, {
        jobId,
        error: job.errorMessage,
        retryCount: job.metadata.retryCount,
      });
    }

    this.jobs.set(jobId, job);
  }

  /**
   * Update job progress
   */
  private async updateJobProgress(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job || job.status !== AsyncJobStatus.RUNNING) {
      return;
    }

    // Update estimated remaining time
    if (job.startedAt && job.progress.completedSteps > 0) {
      const elapsed = Date.now() - job.startedAt.getTime();
      const avgTimePerStep = elapsed / job.progress.completedSteps;
      const remainingSteps =
        job.progress.totalSteps - job.progress.completedSteps;
      job.progress.estimatedRemainingMs = remainingSteps * avgTimePerStep;
    }

    this.jobs.set(jobId, job);
  }

  /**
   * Add job to priority queue
   */
  private addToQueue(jobId: string): void {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Insert based on priority
    const priorityOrder = {
      [AsyncJobPriority.CRITICAL]: 0,
      [AsyncJobPriority.URGENT]: 1,
      [AsyncJobPriority.HIGH]: 2,
      [AsyncJobPriority.NORMAL]: 3,
      [AsyncJobPriority.LOW]: 4,
    };

    const jobPriorityValue = priorityOrder[job.priority];
    let insertIndex = this.jobQueue.length;

    // Find correct insertion position
    for (let i = 0; i < this.jobQueue.length; i++) {
      const queuedJobId = this.jobQueue[i];
      if (!queuedJobId) continue;
      const queuedJob = this.jobs.get(queuedJobId);

      if (queuedJob) {
        const queuedPriorityValue = priorityOrder[queuedJob.priority];
        if (jobPriorityValue < queuedPriorityValue) {
          insertIndex = i;
          break;
        }
      }
    }

    this.jobQueue.splice(insertIndex, 0, jobId);

    this.logger.log(`Job added to queue: ${jobId}`, {
      jobId,
      priority: job.priority,
      queuePosition: insertIndex,
      queueLength: this.jobQueue.length,
    });
  }

  /**
   * Get next job from queue
   */
  private getNextJobFromQueue(): string | null {
    return this.jobQueue.shift() || null;
  }

  /**
   * Get queue position
   */
  private getQueuePosition(jobId: string): number {
    return this.jobQueue.indexOf(jobId);
  }

  /**
   * Estimate total steps for job
   */
  private estimateTotalSteps(_dto: CreateAsyncJobDto): number {
    switch (_dto.jobType) {
      case AsyncJobType.BATCH_AUTOMATION:
        return _dto.configuration.tasks?.length || 1;
      case AsyncJobType.DATA_EXTRACTION:
        return _dto.configuration.urls?.length || 1;
      default:
        return 1;
    }
  }

  /**
   * Create session for extraction
   */
  private async createExtractionSession(): Promise<string> {
    // This would create a browser session for data extraction
    // For now, return a mock session ID
    return `extraction_session_${Date.now()}`;
  }

  /**
   * Cleanup on service destruction
   */
  onModuleDestroy() {
    if (this.jobProcessingInterval) {
      clearInterval(this.jobProcessingInterval);
    }

    // Cancel all running jobs
    for (const jobId of this.processingJobs) {
      this.cancelAsyncJob(jobId).catch((err) => {
        this.logger.error(
          `Failed to cancel job during shutdown: ${jobId}`,
          err,
        );
      });
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import {
  CreateBrowserSessionDto,
  BrowserSessionDto,
  BrowserSessionStatus,
  BrowserTabInfoDto,
} from './dto/browser-session.dto';

/**
 * Browser Session Service - Session Lifecycle Management
 *
 * Manages browser session creation, monitoring, and cleanup for the
 * browser-use integration. Provides local-only session management
 * without any cloud dependencies.
 *
 * Key Responsibilities:
 * - Browser session lifecycle management
 * - Tab management and monitoring
 * - Session state tracking
 * - Cleanup and resource management
 * - Local storage and persistence
 */
@Injectable()
export class BrowserSessionService {
  private readonly logger = new Logger(BrowserSessionService.name);
  private readonly sessions: Map<string, BrowserSessionDto> = new Map();
  private readonly sessionCleanupInterval: NodeJS.Timeout;

  constructor() {
    // Start periodic cleanup of expired sessions
    this.sessionCleanupInterval = setInterval(() => {
      this.cleanupExpiredSessions().catch((err) => {
        this.logger.error('Failed to cleanup expired sessions', err);
      });
    }, 60000); // Check every minute
  }

  /**
   * Create a new browser session
   */
  async createSession(
    _dto: CreateBrowserSessionDto,
  ): Promise<BrowserSessionDto> {
    const sessionId = uuidv4();
    const now = new Date();

    this.logger.log(`Creating new browser session: ${sessionId}`, {
      sessionId,
      name: _dto.name,
      headless: _dto.headless,
      viewport: `${_dto.viewportWidth}x${_dto.viewportHeight}`,
    });

    try {
      // Create initial session object
      const session: BrowserSessionDto = {
        sessionId,
        name: _dto.name || `Browser Session ${Date.now()}`,
        status: BrowserSessionStatus.CREATING,
        browserPid: 0, // Will be set when browser starts
        createdAt: now,
        lastActivityAt: now,
        viewport: {
          width: _dto.viewportWidth || 1920,
          height: _dto.viewportHeight || 1080,
        },
        config: {
          headless: _dto.headless || false,
          devtools: _dto.devtools || false,
          userAgent: _dto.userAgent,
          proxy: _dto.proxy
            ? {
                server: _dto.proxy.server,
                username: _dto.proxy.username,
              }
            : undefined,
          profilePath: _dto.profilePath,
        },
        tabs: [],
        activeTabId: '',
        statistics: {
          totalTabs: 0,
          totalPageLoads: 0,
          totalScreenshots: 0,
          totalActions: 0,
          upTimeMs: 0,
        },
        metadata: _dto.metadata,
      };

      // Store session
      this.sessions.set(sessionId, session);

      // Initialize browser (mock implementation - in production would start actual browser)
      await this.initializeBrowserSession(session, _dto);

      // Create initial tabs if specified
      if (_dto.initialUrls && _dto.initialUrls.length > 0) {
        for (const url of _dto.initialUrls) {
          await this.createTab(sessionId, { url, makeActive: false });
        }

        // Make first tab active
        if (session.tabs.length > 0 && session.tabs[0]) {
          session.activeTabId = session.tabs[0].tabId;
        }
      } else {
        // Create default blank tab
        const tab = await this.createTab(sessionId, {
          url: 'about:blank',
          title: 'New Tab',
          makeActive: true,
        });
        session.activeTabId = tab.tabId;
      }

      // Update session status
      session.status = BrowserSessionStatus.ACTIVE;
      this.sessions.set(sessionId, session);

      this.logger.log(`Browser session created successfully: ${sessionId}`, {
        sessionId,
        tabsCreated: session.tabs.length,
        status: session.status,
      });

      return session;
    } catch (_err) {
      this.logger.error(`Failed to create browser session: ${sessionId}`, _err);

      // Update session with error status
      const errorSession = this.sessions.get(sessionId);
      if (errorSession) {
        errorSession.status = BrowserSessionStatus.ERROR;
        errorSession.errorInfo = {
          message: _err instanceof Error ? _err.message : String(_err),
          code: 'SESSION_CREATION_FAILED',
          timestamp: new Date(),
          details: {
            error: _err instanceof Error ? _err.stack : String(_err),
          },
        };
        this.sessions.set(sessionId, errorSession);
      }

      throw _err;
    }
  }

  /**
   * Get browser session by ID
   */
  async getSession(sessionId: string): Promise<BrowserSessionDto | null> {
    const session = this.sessions.get(sessionId);

    if (!session) {
      return null;
    }

    // Update uptime statistics
    session.statistics.upTimeMs = Date.now() - session.createdAt.getTime();

    return session;
  }

  /**
   * Get all browser sessions
   */
  async getAllSessions(): Promise<BrowserSessionDto[]> {
    const sessions = Array.from(this.sessions.values());

    // Update uptime for all sessions
    sessions.forEach((session) => {
      session.statistics.upTimeMs = Date.now() - session.createdAt.getTime();
    });

    return sessions;
  }

  /**
   * Close browser session
   */
  async closeSession(sessionId: string): Promise<void> {
    this.logger.log(`Closing browser session: ${sessionId}`);

    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session not found: ${sessionId}`);
    }

    try {
      // Update session status
      session.status = BrowserSessionStatus.CLOSING;
      session.lastActivityAt = new Date();

      // Close all tabs
      for (const tab of session.tabs) {
        await this.closeTab(sessionId, tab.tabId);
      }

      // Terminate browser process (mock - in production would kill actual process)
      await this.terminateBrowserSession(session);

      // Update final status
      session.status = BrowserSessionStatus.CLOSED;
      session.closedAt = new Date();

      this.logger.log(`Browser session closed successfully: ${sessionId}`, {
        sessionId,
        upTimeMs: session.statistics.upTimeMs,
        tabsProcessed: session.statistics.totalTabs,
      });
    } catch (_err) {
      this.logger.error(`Failed to close browser session: ${sessionId}`, _err);

      session.status = BrowserSessionStatus.ERROR;
      session.errorInfo = {
        message: _err instanceof Error ? _err.message : String(_err),
        code: 'SESSION_CLOSE_FAILED',
        timestamp: new Date(),
      };

      throw _err;
    }
  }

  /**
   * Create new tab in session
   */
  async createTab(
    sessionId: string,
    options?: {
      url?: string;
      title?: string;
      makeActive?: boolean;
    },
  ): Promise<BrowserTabInfoDto> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session not found: ${sessionId}`);
    }

    const tabId = uuidv4();
    const now = new Date();

    const tab: BrowserTabInfoDto = {
      tabId,
      url: options?.url || 'about:blank',
      title: options?.title || 'New Tab',
      active: options?.makeActive ?? false,
      loading: options?.url !== 'about:blank',
      faviconUrl: undefined,
      createdAt: now,
      lastActivityAt: now,
    };

    // Add tab to session
    session.tabs.push(tab);
    session.statistics.totalTabs++;
    session.lastActivityAt = now;

    if (options?.makeActive) {
      // Deactivate other tabs
      session.tabs.forEach((t) => {
        if (t.tabId !== tabId) {
          t.active = false;
        }
      });
      session.activeTabId = tabId;
    }

    this.sessions.set(sessionId, session);

    this.logger.log(`Created new tab: ${tabId}`, {
      sessionId,
      tabId,
      url: tab.url,
      active: tab.active,
    });

    return tab;
  }

  /**
   * Close tab in session
   */
  async closeTab(sessionId: string, tabId: string): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session not found: ${sessionId}`);
    }

    const tabIndex = session.tabs.findIndex((t) => t.tabId === tabId);
    if (tabIndex === -1) {
      throw new Error(`Tab not found: ${tabId}`);
    }

    // Remove tab
    session.tabs.splice(tabIndex, 1);
    session.lastActivityAt = new Date();

    // If closed tab was active, make another tab active
    if (
      session.activeTabId === tabId &&
      session.tabs.length > 0 &&
      session.tabs[0]
    ) {
      session.activeTabId = session.tabs[0].tabId;
      session.tabs[0].active = true;
    } else if (session.tabs.length === 0) {
      session.activeTabId = '';
    }

    this.sessions.set(sessionId, session);

    this.logger.log(`Closed tab: ${tabId}`, {
      sessionId,
      tabId,
      remainingTabs: session.tabs.length,
    });
  }

  /**
   * Switch active tab
   */
  async switchTab(sessionId: string, tabId: string): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session not found: ${sessionId}`);
    }

    const tab = session.tabs.find((t) => t.tabId === tabId);
    if (!tab) {
      throw new Error(`Tab not found: ${tabId}`);
    }

    // Deactivate all tabs
    session.tabs.forEach((t) => {
      t.active = false;
    });

    // Activate target tab
    tab.active = true;
    session.activeTabId = tabId;
    session.lastActivityAt = new Date();

    this.sessions.set(sessionId, session);

    this.logger.log(`Switched to tab: ${tabId}`, {
      sessionId,
      tabId,
      url: tab.url,
    });
  }

  /**
   * Update session activity
   */
  async updateActivity(
    sessionId: string,
    activity: {
      actionType?: string;
      screenshot?: boolean;
      pageLoad?: boolean;
    },
  ): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      return;
    }

    session.lastActivityAt = new Date();
    session.statistics.totalActions++;

    if (activity.screenshot) {
      session.statistics.totalScreenshots++;
    }

    if (activity.pageLoad) {
      session.statistics.totalPageLoads++;
    }

    this.sessions.set(sessionId, session);
  }

  /**
   * Initialize browser session (mock implementation)
   */
  private async initializeBrowserSession(
    session: BrowserSessionDto,
    _dto: CreateBrowserSessionDto,
  ): Promise<void> {
    // In production, this would:
    // 1. Start browser process with specified configuration
    // 2. Connect to CDP (Chrome DevTools Protocol)
    // 3. Set up event listeners
    // 4. Configure viewport, user agent, etc.

    // Mock browser PID
