/**
 * Cache Key Generator - Intelligent Cache Key Management
 *
 * Provides systematic cache key generation with namespace support,
 * collision prevention, and performance optimization. Ensures
 * consistent key naming across the application.
 *
 * Features:
 * - Hierarchical key generation with namespacing
 * - Hash-based key normalization for long keys
 * - Collision detection and prevention
 * - Key validation and sanitization
 * - Performance metrics integration
 * - Support for complex object-based keys
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import { Injectable, Logger } from '@nestjs/common';
import { createHash } from 'crypto';

/**
 * Cache key generation options
 */
interface KeyGenerationOptions {
  namespace?: string;
  version?: string;
  includeTimestamp?: boolean;
  maxLength?: number;
  hashLongKeys?: boolean;
}

/**
 * Cache key metadata for tracking and debugging
 */
interface KeyMetadata {
  originalKey: string;
  generatedKey: string;
  namespace?: string;
  version?: string;
  hashedKey: boolean;
  timestamp?: number;
}

/**
 * Cache key statistics for monitoring
 */
interface KeyStats {
  totalGenerated: number;
  hashedKeys: number;
  namespaceUsage: Map<string, number>;
  avgKeyLength: number;
}

/**
 * Cache key generator service
 */
@Injectable()
export class CacheKeyGenerator {
  private readonly logger = new Logger(CacheKeyGenerator.name);
  private readonly keyRegistry = new Map<string, KeyMetadata>();
  private readonly stats: KeyStats = {
    totalGenerated: 0,
    hashedKeys: 0,
    namespaceUsage: new Map(),
    avgKeyLength: 0,
  };

  // Configuration constants
  private readonly DEFAULT_NAMESPACE = 'bytebot';
  private readonly MAX_KEY_LENGTH = 250; // Redis key length limit is 512MB, but keep reasonable
  private readonly HASH_THRESHOLD = 200; // Hash keys longer than this
  private readonly KEY_SEPARATOR = ':';

  constructor() {
    this.logger.log('Cache Key Generator initialized');
    this.logger.log(
      `Max key length: ${this.MAX_KEY_LENGTH}, Hash threshold: ${this.HASH_THRESHOLD}`,
    );
  }

  /**
   * Generate cache key with intelligent normalization
   *
   * @param key Base key or key components
   * @param namespace Optional namespace
   * @param options Additional key generation options
   * @returns string Generated cache key
   */
  generate(
    key: string | string[] | Record<string, any>,
    namespace?: string,
    options: KeyGenerationOptions = {},
  ): string {
    const operationId = `keygen_${Date.now()}`;

    try {
      // Normalize the input key
      const normalizedKey = this.normalizeKey(key);

      // Build key components
      const keyComponents: string[] = [];

      // Add namespace
      const keyNamespace =
        namespace || options.namespace || this.DEFAULT_NAMESPACE;
      keyComponents.push(keyNamespace);

      // Add version if specified
      if (options.version) {
        keyComponents.push(`v${options.version}`);
      }

      // Add main key
      keyComponents.push(normalizedKey);

      // Add timestamp if requested
      if (options.includeTimestamp) {
        keyComponents.push(Date.now().toString());
      }

      // Join components
      let fullKey = keyComponents.join(this.KEY_SEPARATOR);

      // Handle long keys
      const shouldHash =
        options.hashLongKeys !== false &&
        fullKey.length > (options.maxLength || this.HASH_THRESHOLD);

      if (shouldHash) {
        fullKey = this.hashKey(fullKey, keyNamespace);
        this.stats.hashedKeys++;
      }

      // Validate final key
      this.validateKey(fullKey);

      // Record metadata
      const metadata: KeyMetadata = {
        originalKey: this.keyToString(key),
        generatedKey: fullKey,
        namespace: keyNamespace,
        version: options.version,
        hashedKey: shouldHash,
        timestamp: options.includeTimestamp ? Date.now() : undefined,
      };

      this.keyRegistry.set(fullKey, metadata);
      this.updateStats(keyNamespace, fullKey.length);

      this.logger.debug(
        `[${operationId}] Generated key: ${fullKey} (original: ${metadata.originalKey})`,
      );

      return fullKey;
    } catch (_error) {
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';
      this.logger.error(
        `[${operationId}] Key generation failed: ${errorMessage}`,
      );

      // Fallback to simple key generation
      const fallbackKey = `${namespace || this.DEFAULT_NAMESPACE}${this.KEY_SEPARATOR}${this.keyToString(key)}`;
      this.logger.warn(`Using fallback key: ${fallbackKey}`);
      return fallbackKey;
    }
  }

  /**
   * Generate key for API response caching
   *
   * @param method HTTP method
   * @param path Request path
   * @param queryParams Query parameters
   * @param userId Optional user ID for user-specific caching
   * @returns string Generated API cache key
   */
  generateApiKey(
    method: string,
    path: string,
    queryParams?: Record<string, any>,
    userId?: string,
  ): string {
    const keyParts = [
      'api',
      method.toLowerCase(),
      path.replace(/\//g, '_').replace(/^_/, ''),
    ];

    if (queryParams && Object.keys(queryParams).length > 0) {
      // Sort query params for consistent key generation
      const sortedParams = Object.keys(queryParams)
        .sort()
        .reduce(
          (result, key) => {
            result[key] = queryParams[key];
            return result;
          },
          {} as Record<string, any>,
        );

      keyParts.push(this.hashObject(sortedParams));
    }

    if (userId) {
      keyParts.push(`user_${userId}`);
    }

    return this.generate(keyParts, 'api');
  }

  /**
   * Generate key for database query caching
   *
   * @param table Database table name
   * @param operation Database operation
   * @param params Query parameters
   * @returns string Generated database cache key
   */
  generateDbKey(
    table: string,
    operation: string,
    params?: Record<string, any>,
  ): string {
    const keyParts = ['db', table, operation];

    if (params && Object.keys(params).length > 0) {
      keyParts.push(this.hashObject(params));
    }

    return this.generate(keyParts, 'database');
  }

  /**
   * Generate key for task-related caching
   *
   * @param taskId Task identifier
   * @param operation Task operation
   * @param additionalParams Additional parameters
   * @returns string Generated task cache key
   */
  generateTaskKey(
    taskId: string,
    operation: string,
    additionalParams?: Record<string, any>,
  ): string {
    const keyParts = ['task', taskId, operation];

    if (additionalParams && Object.keys(additionalParams).length > 0) {
      keyParts.push(this.hashObject(additionalParams));
    }

    return this.generate(keyParts, 'tasks');
  }

  /**
   * Generate pattern for cache invalidation
   *
   * @param namespace Namespace to invalidate
   * @param pattern Optional pattern within namespace
   * @returns string Invalidation pattern
   */
  generateInvalidationPattern(namespace: string, pattern?: string): string {
    let invalidationPattern = `${namespace}${this.KEY_SEPARATOR}*`;

    if (pattern) {
      invalidationPattern = `${namespace}${this.KEY_SEPARATOR}${pattern}*`;
    }

    this.logger.debug(`Generated invalidation pattern: ${invalidationPattern}`);
    return invalidationPattern;
  }

  /**
   * Get key metadata
   *
   * @param key Cache key
   * @returns KeyMetadata | undefined Key metadata if found
   */
  getKeyMetadata(key: string): KeyMetadata | undefined {
    return this.keyRegistry.get(key);
  }

  /**
   * Get key generation statistics
   *
   * @returns KeyStats Current key generation statistics
   */
  getStats(): KeyStats {
    return {
      totalGenerated: this.stats.totalGenerated,
      hashedKeys: this.stats.hashedKeys,
      namespaceUsage: new Map(this.stats.namespaceUsage),
      avgKeyLength: this.stats.avgKeyLength,
    };
  }

  /**
   * Clear key generation statistics
   */
  clearStats(): void {
    this.stats.totalGenerated = 0;
    this.stats.hashedKeys = 0;
    this.stats.namespaceUsage.clear();
    this.stats.avgKeyLength = 0;
    this.keyRegistry.clear();

    this.logger.log('Cache key statistics cleared');
  }

  /**
   * Normalize key input to string
   */
  private normalizeKey(key: string | string[] | Record<string, any>): string {
    if (typeof key === 'string') {
      return this.sanitizeKey(key);
    }

    if (Array.isArray(key)) {
      return key.map((k) => this.sanitizeKey(k)).join(this.KEY_SEPARATOR);
    }

    if (typeof key === 'object' && key !== null) {
      return this.hashObject(key);
    }

    return this.sanitizeKey(String(key));
  }

  /**
   * Sanitize individual key component
   */
  private sanitizeKey(key: string): string {
    return key
      .replace(/[^a-zA-Z0-9_\-.]/g, '_') // Replace invalid characters
      .replace(/_+/g, '_') // Collapse multiple underscores
      .replace(/^_|_$/g, '') // Remove leading/trailing underscores
      .toLowerCase();
  }

  /**
   * Hash long keys for performance and storage efficiency
   */
  private hashKey(key: string, namespace: string): string {
    const hash = createHash('sha256')
      .update(key)
      .digest('hex')
      .substring(0, 16);
    return `${namespace}${this.KEY_SEPARATOR}hash_${hash}`;
  }

  /**
   * Hash object to consistent string representation
   */
  private hashObject(obj: Record<string, any>): string {
    // Sort keys for consistent hashing
    const sortedObj = Object.keys(obj)
      .sort()
      .reduce(
        (result, key) => {
          result[key] = obj[key];
          return result;
        },
        {} as Record<string, any>,
      );

    const objString = JSON.stringify(sortedObj);
    return createHash('md5').update(objString).digest('hex').substring(0, 12);
  }

  /**
   * Convert key input to string for logging
   */
  private keyToString(key: string | string[] | Record<string, any>): string {
    if (typeof key === 'string') {
      return key;
    }

    if (Array.isArray(key)) {
      return key.join(', ');
    }

    return JSON.stringify(key);
  }

  /**
   * Validate generated key
   */
  private validateKey(key: string): void {
    if (!key || key.length === 0) {
      throw new Error('Generated key is empty');
    }

    if (key.length > this.MAX_KEY_LENGTH) {
      throw new Error(
        `Generated key exceeds maximum length: ${key.length} > ${this.MAX_KEY_LENGTH}`,
      );
    }

    // Check for invalid characters that might cause issues
    if (/[\s\r\n\t]/.test(key)) {
      throw new Error('Generated key contains whitespace characters');
    }
  }

  /**
   * Update key generation statistics
   */
  private updateStats(namespace: string, keyLength: number): void {
    this.stats.totalGenerated++;

    // Update namespace usage
    const currentCount = this.stats.namespaceUsage.get(namespace) || 0;
    this.stats.namespaceUsage.set(namespace, currentCount + 1);

    // Update average key length
    this.stats.avgKeyLength =
      (this.stats.avgKeyLength * (this.stats.totalGenerated - 1) + keyLength) /
      this.stats.totalGenerated;
  }
}

/**
 * Cache Module - Redis-based Caching Infrastructure
 *
 * Provides comprehensive caching capabilities using Redis with advanced
 * patterns including cache-aside, write-through, and cache warming.
 * Designed for high-performance enterprise applications.
 *
 * Features:
 * - Redis integration with connection pooling
 * - Cache-aside and write-through patterns
 * - Intelligent cache key generation
 * - Cache invalidation strategies
 * - Performance metrics and monitoring
 * - TTL management and cache warming
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import { Module, Global, Logger } from '@nestjs/common';
import { CacheModule as NestCacheModule } from '@nestjs/cache-manager';
import { CacheService } from './cache.service';
import { CacheKeyGenerator } from './cache-key.generator';
import * as redisStore from 'cache-manager-redis-store';

/**
 * Cache configuration for enterprise-grade Redis caching
 */
interface CacheConfig {
  store: any; // Redis store for cache manager
  host: string;
  port: number;
  ttl: number;
  max: number;
  password?: string;
  db?: number;
}

/**
 * Global cache module providing Redis-based caching throughout the application
 */
@Global()
@Module({
  imports: [
    NestCacheModule.registerAsync({
      useFactory: (): CacheConfig => {
        const _logger = new Logger('CacheModule');

        const config: CacheConfig = {
          store: redisStore,
          host: process.env.REDIS_HOST || 'localhost',
          port: parseInt(process.env.REDIS_PORT || '6379', 10),
          ttl: parseInt(process.env.CACHE_TTL || '300', 10), // 5 minutes default
          max: parseInt(process.env.CACHE_MAX_ITEMS || '1000', 10),
          password: process.env.REDIS_PASSWORD,
          db: parseInt(process.env.REDIS_DB || '0', 10),
        };

        _logger.log('Cache module configuration:', {
          host: config.host,
          port: config.port,
          ttl: config.ttl,
          maxItems: config.max,
          database: config.db,
        });

        return config;
      },
    }),
  ],
  providers: [CacheService, CacheKeyGenerator],
  exports: [CacheService, CacheKeyGenerator, NestCacheModule],
})
export class CacheModule {
  private readonly logger = new Logger(CacheModule.name);

  constructor() {
    this.logger.log('Redis Cache Module initialized');
    this.logger.log('Cache patterns: cache-aside, write-through');
    this.logger.log('Features: TTL management, key generation, metrics');
  }
}

/**
 * Cache Service - Enterprise-grade Redis Caching Implementation
 *
 * Provides high-performance caching with advanced patterns and monitoring.
 * Implements cache-aside, write-through, and cache warming strategies
 * with comprehensive metrics and intelligent cache key management.
 *
 * Features:
 * - Redis-based distributed caching
 * - Cache-aside and write-through patterns
 * - Intelligent TTL management
 * - Cache hit/miss metrics
 * - Bulk operations and cache warming
 * - JSON serialization/deserialization
 * - Error resilience and fallback strategies
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import { Injectable, Logger, Inject } from '@nestjs/common';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import { CacheKeyGenerator } from './cache-key.generator';
import { MetricsService } from '../metrics/metrics.service';

/**
 * Cache operation types for metrics tracking
 */
type CacheOperation = 'get' | 'set' | 'del' | 'mget' | 'mset' | 'warm';

/**
 * Cache options for fine-grained control
 */
interface CacheOptions {
  ttl?: number;
  namespace?: string;
  compress?: boolean;
  serialize?: boolean;
}

/**
 * Cache statistics for monitoring
 */
interface CacheStats {
  hits: number;
  misses: number;
  hitRate: number;
  totalOperations: number;
  avgResponseTime: number;
}

/**
 * Enterprise cache service with Redis backend
 */
@Injectable()
export class CacheService {
  private readonly logger = new Logger(CacheService.name);
  private stats: CacheStats = {
    hits: 0,
    misses: 0,
    hitRate: 0,
    totalOperations: 0,
    avgResponseTime: 0,
  };

  constructor(
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly keyGenerator: CacheKeyGenerator,
    private readonly metricsService: MetricsService,
  ) {
    this.logger.log('Cache Service initialized with Redis backend');
    this.startStatsCollection();
  }

  /**
   * Get value from cache (cache-aside pattern)
   *
   * @param key Cache key
   * @param options Cache options
   * @returns Promise<T | null> Cached value or null if not found
   */
  async get<T>(key: string, options: CacheOptions = {}): Promise<T | null> {
    const operationId = `cache_get_${Date.now()}`;
    const startTime = Date.now();

    try {
      const fullKey = this.keyGenerator.generate(key, options.namespace);
      this.logger.debug(`[${operationId}] Cache GET: ${fullKey}`);

      const cachedValue = await this.cacheManager.get<string>(fullKey);
      const duration = Date.now() - startTime;

      if (cachedValue !== undefined && cachedValue !== null) {
        // Cache hit
        this.stats.hits++;
        this.recordOperation('get', 'hit', duration);

        let _result: T;
        if (options.serialize !== false) {
          try {
            _result = JSON.parse(cachedValue);
          } catch {
            _result = cachedValue as unknown as T;
          }
        } else {
          _result = cachedValue as unknown as T;
        }

        this.logger.debug(
          `[${operationId}] Cache HIT: ${fullKey} (${duration}ms)`,
        );
        return _result;
      } else {
        // Cache miss
        this.stats.misses++;
        this.recordOperation('get', 'miss', duration);

        this.logger.debug(
          `[${operationId}] Cache MISS: ${fullKey} (${duration}ms)`,
        );
        return null;
      }
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache GET error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('get', 'error', duration);
      return null; // Graceful fallback
    } finally {
      this.updateStats();
    }
  }

  /**
   * Set value in cache (cache-aside or write-through pattern)
   *
   * @param key Cache key
   * @param value Value to cache
   * @param options Cache options
   */
  async set<T>(
    key: string,
    value: T,
    options: CacheOptions = {},
  ): Promise<void> {
    const operationId = `cache_set_${Date.now()}`;
    const startTime = Date.now();

    try {
      const fullKey = this.keyGenerator.generate(key, options.namespace);
      const ttl = options.ttl || 300; // 5 minutes default

      let cacheValue: string;
      if (options.serialize !== false) {
        cacheValue = JSON.stringify(value);
      } else {
        cacheValue = value as unknown as string;
      }

      this.logger.debug(
        `[${operationId}] Cache SET: ${fullKey} (TTL: ${ttl}s)`,
      );

      await this.cacheManager.set(fullKey, cacheValue, ttl * 1000);

      const duration = Date.now() - startTime;
      this.recordOperation('set', 'success', duration);

      this.logger.debug(
        `[${operationId}] Cache SET completed: ${fullKey} (${duration}ms)`,
      );
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache SET error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('set', 'error', duration);
      // Don't throw - cache errors should be non-fatal
    }
  }

  /**
   * Delete value from cache
   *
   * @param key Cache key
   * @param options Cache options
   */
  async del(key: string, options: CacheOptions = {}): Promise<void> {
    const operationId = `cache_del_${Date.now()}`;
    const startTime = Date.now();

    try {
      const fullKey = this.keyGenerator.generate(key, options.namespace);

      this.logger.debug(`[${operationId}] Cache DEL: ${fullKey}`);

      await this.cacheManager.del(fullKey);

      const duration = Date.now() - startTime;
      this.recordOperation('del', 'success', duration);

      this.logger.debug(
        `[${operationId}] Cache DEL completed: ${fullKey} (${duration}ms)`,
      );
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache DEL error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('del', 'error', duration);
    }
  }

  /**
   * Get multiple values from cache (bulk operation)
   *
   * @param keys Array of cache keys
   * @param options Cache options
   * @returns Promise<Map<string, T>> Map of key-value pairs
   */
  async mget<T>(
    keys: string[],
    options: CacheOptions = {},
  ): Promise<Map<string, T>> {
    const operationId = `cache_mget_${Date.now()}`;
    const startTime = Date.now();
    const results = new Map<string, T>();

    try {
      this.logger.debug(`[${operationId}] Cache MGET: ${keys.length} keys`);

      // Process keys in parallel
      const promises = keys.map(async (key) => {
        const value = await this.get<T>(key, options);
        if (value !== null) {
          results.set(key, value);
        }
      });

      await Promise.all(promises);

      const duration = Date.now() - startTime;
      this.recordOperation('mget', 'success', duration);

      this.logger.debug(
        `[${operationId}] Cache MGET completed: ${results.size}/${keys.length} found (${duration}ms)`,
      );

      return results;
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache MGET error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('mget', 'error', duration);
      return results; // Return partial results
    }
  }

  /**
   * Set multiple values in cache (bulk operation)
   *
   * @param entries Array of key-value pairs
   * @param options Cache options
   */
  async mset<T>(
    entries: Array<{ key: string; value: T }>,
    options: CacheOptions = {},
  ): Promise<void> {
    const operationId = `cache_mset_${Date.now()}`;
    const startTime = Date.now();

    try {
      this.logger.debug(
        `[${operationId}] Cache MSET: ${entries.length} entries`,
      );

      // Process entries in parallel
      const promises = entries.map(({ key, value }) =>
        this.set(key, value, options),
      );

      await Promise.all(promises);

      const duration = Date.now() - startTime;
      this.recordOperation('mset', 'success', duration);

      this.logger.debug(
        `[${operationId}] Cache MSET completed: ${entries.length} entries (${duration}ms)`,
      );
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache MSET error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('mset', 'error', duration);
    }
  }

  /**
   * Warm cache with data (pre-populate frequently accessed data)
   *
   * @param dataProvider Function that provides data for caching
   * @param keys Array of keys to warm
   * @param options Cache options
   */
  async warmCache<T>(
    dataProvider: (key: string) => Promise<T | null>,
    keys: string[],
    options: CacheOptions = {},
  ): Promise<void> {
    const operationId = `cache_warm_${Date.now()}`;
    const startTime = Date.now();

    try {
      this.logger.log(
        `[${operationId}] Cache warming started: ${keys.length} keys`,
      );

      const warmPromises = keys.map(async (key) => {
        try {
          const data = await dataProvider(key);
          if (data !== null) {
            await this.set(key, data, options);
          }
        } catch (_error) {
          this.logger.warn(
            `Cache warming failed for key ${key}: ${_error instanceof Error ? _error.message : 'Unknown error'}`,
          );
        }
      });

      await Promise.all(warmPromises);

      const duration = Date.now() - startTime;
      this.recordOperation('warm', 'success', duration);

      this.logger.log(
        `[${operationId}] Cache warming completed: ${keys.length} keys (${duration}ms)`,
      );
    } catch (_error) {
      const duration = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Cache warming error: ${errorMessage} (${duration}ms)`,
      );

      this.recordOperation('warm', 'error', duration);
    }
  }

  /**
   * Get cache statistics
   *
   * @returns CacheStats Current cache performance statistics
   */
  getStats(): CacheStats {
    return { ...this.stats };
  }

  /**
   * Clear cache statistics
   */
  clearStats(): void {
    this.stats = {
      hits: 0,
      misses: 0,
      hitRate: 0,
      totalOperations: 0,
      avgResponseTime: 0,
    };
    this.logger.log('Cache statistics cleared');
  }

  /**
   * Invalidate cache by pattern
   *
   * @param pattern Key pattern to match (supports wildcards)
   * @param namespace Optional namespace
   */
  async invalidatePattern(pattern: string, _namespace?: string): Promise<void> {
    const operationId = `cache_invalidate_${Date.now()}`;

    try {
      // For Redis, we would use SCAN with pattern matching
      // This is a simplified implementation
      this.logger.warn(
        `[${operationId}] Pattern invalidation requested: ${pattern} (not fully implemented)`,
      );

      // TODO: Implement Redis SCAN-based pattern invalidation
      // This would require direct Redis client access
    } catch (_error) {
      const errorMessage =
        _error instanceof Error ? _error.message : 'Unknown _error';
      this.logger.error(
        `[${operationId}] Pattern invalidation error: ${errorMessage}`,
      );
    }
  }

  /**
   * Record cache operation metrics
   */
  private recordOperation(
    operation: CacheOperation,
    result: 'hit' | 'miss' | 'success' | 'error',
    duration: number,
  ): void {
    try {
      // Record metrics with MetricsService
      this.metricsService.recordCacheOperation?.(operation, result, duration);
    } catch (_error) {
      // Ignore metrics errors to prevent cascading failures
      this.logger.debug(
        `Failed to record cache metrics: ${_error instanceof Error ? _error.message : 'Unknown _error'}`,
      );
    }
  }

  /**
   * Update cache statistics
   */
  private updateStats(): void {
    this.stats.totalOperations = this.stats.hits + this.stats.misses;
    if (this.stats.totalOperations > 0) {
      this.stats.hitRate = (this.stats.hits / this.stats.totalOperations) * 100;
    }
  }

  /**
   * Start periodic statistics collection
   */
  private startStatsCollection(): void {
    // Log cache statistics every 5 minutes
    setInterval(() => {
      if (this.stats.totalOperations > 0) {
        this.logger.log('Cache Performance Stats:', {
          hits: this.stats.hits,
          misses: this.stats.misses,
          hitRate: `${this.stats.hitRate.toFixed(2)}%`,
          totalOperations: this.stats.totalOperations,
        });
      }
    }, 300000); // 5 minutes
  }
}

