/**
 * Enterprise Security Exception Filter - Secure Error Handling
 *
 * This filter provides comprehensive error handling with security-focused
 * response sanitization to prevent information disclosure while maintaining
 * proper error logging and monitoring for security incidents.
 *
 * @fileoverview Enterprise-grade secure error handling and response sanitization
 * @version 1.0.0
 * @author Input Validation & API Security Specialist
 */

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { ThrottlerException } from '@nestjs/throttler';

/**
 * Security-focused error classification
 */
enum SecurityErrorType {
  VALIDATION_ERROR = 'validation_error',
  AUTHENTICATION_ERROR = 'authentication_error',
  AUTHORIZATION_ERROR = 'authorization_error',
  RATE_LIMIT_ERROR = 'rate_limit_error',
  SECURITY_VIOLATION = 'security_violation',
  SYSTEM_ERROR = 'system_error',
  INPUT_ERROR = 'input_error',
}

/**
 * Secure error response structure
 */
interface SecureErrorResponse {
  statusCode: number;
  error: string;
  message: string;
  timestamp: string;
  path: string;
  requestId: string;
  // Only include in development
  details?: any;
  stack?: string;
}

/**
 * Security metrics for error tracking
 */
interface _SecurityErrorMetrics {
  errorType: SecurityErrorType;
  statusCode: number;
  clientIP: string;
  userAgent: string;
  endpoint: string;
  timestamp: Date;
  riskScore: number;
}

@Catch()
export class SecurityExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(SecurityExceptionFilter.name);

  // Track error patterns for security analysis
  private errorPatterns = new Map<
    string,
    {
      count: number;
      lastSeen: Date;
      riskScore: number;
    }
  >();

  /**
   * Handle all exceptions with security-focused processing
   */
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const request = ctx.getRequest<Request>();
    const response = ctx.getResponse<Response>();

    // Generate request ID for tracking (use existing or create new)
    const requestId =
      (request.headers['x-correlation-id'] as string) ||
      (request.headers['x-request-id'] as string) ||
      `error-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // Classify and analyze the exception
    const errorAnalysis = this.analyzeException(exception, request);

    // Create secure error response (never leak sensitive info)
    const secureResponse = this.createSecureResponse(
      exception,
      request,
      requestId,
      errorAnalysis,
    );

    // Log security event with full details (for internal use)
    this.logSecurityEvent(exception, request, errorAnalysis, requestId);

    // Track error patterns for threat detection
    this.trackErrorPattern(request, errorAnalysis);

    // Check for security attack patterns
    if (errorAnalysis.riskScore >= 7) {
      this.handleHighRiskError(request, errorAnalysis, requestId);
    }

    // Set security headers
    response.setHeader('X-Request-ID', requestId);
    response.setHeader('X-Content-Type-Options', 'nosniff');
    response.setHeader('X-Frame-Options', 'DENY');

    // Send secure response
    response.response.status(secureResponse.statusCode).json(secureResponse);
  }

  /**
   * Analyze exception for security classification and risk assessment
   */
  private analyzeException(
    exception: unknown,
    request: Request,
  ): {
    errorType: SecurityErrorType;
    statusCode: number;
    riskScore: number;
    threatIndicators: string[];
    isSecurityRelated: boolean;
  } {
    let errorType = SecurityErrorType.SYSTEM_ERROR;
    let statusCode = HttpStatus.INTERNAL_SERVER_ERROR;
    let riskScore = 1;
    const threatIndicators: string[] = [];

    // Analyze exception type
    if (exception instanceof HttpException) {
      statusCode = exception.getStatus();

      // Classify by HTTP status code
      switch (statusCode) {
        case HttpStatus.BAD_REQUEST:
          errorType = SecurityErrorType.INPUT_ERROR;
          riskScore = 2;
          break;
        case HttpStatus.UNAUTHORIZED:
          errorType = SecurityErrorType.AUTHENTICATION_ERROR;
          riskScore = 4;
          threatIndicators.push('auth_failure');
          break;
        case HttpStatus.FORBIDDEN:
          errorType = SecurityErrorType.AUTHORIZATION_ERROR;
          riskScore = 5;
          threatIndicators.push('access_denied');
          break;
        case HttpStatus.TOO_MANY_REQUESTS:
          errorType = SecurityErrorType.RATE_LIMIT_ERROR;
          riskScore = 3;
          threatIndicators.push('rate_limit_exceeded');
          break;
        default:
          if (statusCode >= 400 && statusCode < 500) {
            riskScore = 3;
          }
      }

      // Check for specific exception types
      if (exception instanceof ThrottlerException) {
        errorType = SecurityErrorType.RATE_LIMIT_ERROR;
        riskScore = 4;
        threatIndicators.push('throttle_violation');
      }

      // Analyze error message for security patterns
      const message = exception.message?.toLowerCase() || '';

      if (message.includes('validation') || message.includes('sanitization')) {
        errorType = SecurityErrorType.VALIDATION_ERROR;
        riskScore += 1;
      }

      if (
        message.includes('xss') ||
        message.includes('injection') ||
        message.includes('malicious')
      ) {
        errorType = SecurityErrorType.SECURITY_VIOLATION;
        riskScore += 4;
        threatIndicators.push('attack_detected');
      }
    }

    // Increase risk score for repeated errors from same client
    const clientIdentifier = this.getClientIdentifier(request);
    const existingPattern = this.errorPatterns.get(clientIdentifier);
    if (existingPattern && existingPattern.count > 5) {
      riskScore += 2;
      threatIndicators.push('repeated_errors');
    }

    return {
      errorType,
      statusCode,
      riskScore: Math.min(10, riskScore), // Cap at 10
      threatIndicators,
      isSecurityRelated: riskScore >= 4 || threatIndicators.length > 0,
    };
  }

  /**
   * Create secure error response that doesn't leak sensitive information
   */
  private createSecureResponse(
    exception: unknown,
    request: Request,
    requestId: string,
    errorAnalysis: any,
  ): SecureErrorResponse {
    const isDevelopment = process.env.NODE_ENV === 'development';

    // Base secure response
    const response: SecureErrorResponse = {
      statusCode: errorAnalysis.statusCode,
      error: this.getSecureErrorName(errorAnalysis.statusCode),
      message: this.getSecureErrorMessage(exception, errorAnalysis),
      timestamp: new Date().toISOString(),
      path: request.path,
      requestId,
    };

    // Only include detailed information in development
    if (isDevelopment) {
      response.details = this.sanitizeErrorDetails(exception);

      if (exception instanceof Error && exception.stack) {
        response.stack = exception.stack;
      }
    }

    return response;
  }

  /**
   * Get secure error name based on status code
   */
  private getSecureErrorName(statusCode: number): string {
    const errorNames = {
      400: 'Bad Request',
      401: 'Unauthorized',
      403: 'Forbidden',
      404: 'Not Found',
      405: 'Method Not Allowed',
      409: 'Conflict',
      422: 'Unprocessable Entity',
      429: 'Too Many Requests',
      500: 'Internal Server Error',
      502: 'Bad Gateway',
      503: 'Service Unavailable',
      504: 'Gateway Timeout',
    };

    return errorNames[statusCode] || 'Unknown Error';
  }

  /**
   * Get secure error message that doesn't leak sensitive information
   */
  private getSecureErrorMessage(
    exception: unknown,
    errorAnalysis: any,
  ): string {
    // For security violations, use generic message
    if (errorAnalysis.errorType === SecurityErrorType.SECURITY_VIOLATION) {
      return 'Request blocked due to security policy violation';
    }

    // For rate limiting
    if (errorAnalysis.errorType === SecurityErrorType.RATE_LIMIT_ERROR) {
      return 'Too many requests. Please try again later';
    }

    // For validation errors, provide safe message
    if (errorAnalysis.errorType === SecurityErrorType.VALIDATION_ERROR) {
      return 'Invalid input provided. Please check your request';
    }

    // For HTTP exceptions, use the message but sanitize it
    if (exception instanceof HttpException) {
      const message = exception.message;
      return this.sanitizeErrorMessage(message);
    }

    // Generic message for other errors
    return 'An error occurred while processing your request';
  }

  /**
   * Sanitize error message to prevent information disclosure
   */
  private sanitizeErrorMessage(message: string): string {
    // Remove sensitive patterns
    const sanitizedMessage = message
      // Remove file paths
      .replace(/\/[a-zA-Z0-9/_-]+/g, '[PATH_REMOVED]')
      // Remove database information
      .replace(/database|table|column|sql|query/gi, '[DB_INFO_REMOVED]')
      // Remove system information
      .replace(/system|process|memory|cpu/gi, '[SYSTEM_INFO_REMOVED]')
      // Remove stack traces
      .replace(/at [a-zA-Z0-9._]+\([^)]+\)/g, '[STACK_REMOVED]')
      // Remove sensitive environment variables
      .replace(
        /NODE_ENV|API_KEY|SECRET|PASSWORD|TOKEN/gi,
        '[SENSITIVE_REMOVED]',
      );

    return sanitizedMessage.substring(0, 200); // Limit message length
  }

  /**
   * Sanitize error details for development responses
   */
  private sanitizeErrorDetails(exception: unknown): any {
    if (!(exception instanceof Error)) {
      return null;
    }

    return {
      name: exception.name,
      cause: (exception as any).cause || 'Unknown',
      // Don't include the full stack trace in JSON response
    };
  }

  /**
   * Log security event with full details for monitoring
   */
  private logSecurityEvent(
    exception: unknown,
    request: Request,
    errorAnalysis: any,
    requestId: string,
  ): void {
    const logData = {
      event: 'security_exception',
      requestId,
      errorType: errorAnalysis.errorType,
      statusCode: errorAnalysis.statusCode,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      isSecurityRelated: errorAnalysis.isSecurityRelated,
      request: {
        method: request.method,
        url: request.url,
        path: request.path,
        query: request.query,
        headers: this.sanitizeHeaders(request.headers),
        clientIP: this.getClientIP(request),
        userAgent: request.headers['user-agent'],
      },
      exception: {
        name: exception instanceof Error ? exception.name : 'Unknown',
        message:
          exception instanceof Error ? exception.message : String(exception),
        stack: exception instanceof Error ? exception.stack : undefined,
      },
      timestamp: new Date().toISOString(),
    };

    // Log at appropriate level based on risk score
    if (errorAnalysis.riskScore >= 7) {
      this.logger.error(`[${requestId}] HIGH RISK SECURITY EXCEPTION`, logData);
    } else if (errorAnalysis.isSecurityRelated) {
      this.logger.warn(`[${requestId}] Security-related exception`, logData);
    } else {
      this.logger.debug(`[${requestId}] Application exception`, logData);
    }
  }

  /**
   * Track error patterns for threat detection
   */
  private trackErrorPattern(request: Request, errorAnalysis: any): void {
    const clientIdentifier = this.getClientIdentifier(request);
    const now = new Date();

    if (!this.errorPatterns.has(clientIdentifier)) {
      this.errorPatterns.set(clientIdentifier, {
        count: 1,
        lastSeen: now,
        riskScore: errorAnalysis.riskScore,
      });
    } else {
      const pattern = this.errorPatterns.get(clientIdentifier)!;
      pattern.count += 1;
      pattern.lastSeen = now;
      pattern.riskScore = Math.max(pattern.riskScore, errorAnalysis.riskScore);
    }

    // Clean up old patterns (older than 1 hour)
    this.cleanupErrorPatterns();
  }

  /**
   * Handle high-risk security errors
   */
  private handleHighRiskError(
    request: Request,
    errorAnalysis: any,
    requestId: string,
  ): void {
    const clientIP = this.getClientIP(request);
    const userAgent = request.headers['user-agent'];

    this.logger.error(`[${requestId}] HIGH RISK SECURITY EVENT DETECTED`, {
      event: 'high_risk_error',
      requestId,
      clientIP,
      userAgent,
      endpoint: request.path,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      recommendation:
        'Consider implementing additional security measures for this client',
      timestamp: new Date().toISOString(),
    });

    // In a production environment, you might:
    // - Send alert to security team
    // - Add IP to temporary blocklist
    // - Increase monitoring for this client
    // - Trigger additional security measures
  }

  /**
   * Generate client identifier for tracking
   */
  private getClientIdentifier(request: Request): string {
    const ip = this.getClientIP(request);
    const userAgent = (request.headers['user-agent'] || '').substring(0, 50);
    return `${ip}:${userAgent}`.replace(/[^a-zA-Z0-9:.-]/g, '_');
  }

  /**
   * Get client IP address
   */
  private getClientIP(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0] ||
      (request.headers['x-real-ip'] as string) ||
      request.connection.remoteAddress ||
      request.socket.remoteAddress ||
      'unknown'
    );
  }

  /**
   * Sanitize headers to remove sensitive information
   */
  private sanitizeHeaders(headers: any): any {
    const sanitized = { ...headers };

    const sensitiveHeaders = [
      'authorization',
      'cookie',
      'x-api-key',
      'x-auth-token',
      'proxy-authorization',
    ];

    sensitiveHeaders.forEach((header) => {
      if (sanitized[header]) {
        sanitized[header] = '[REDACTED]';
      }
    });

    return sanitized;
  }

  /**
   * Clean up old error patterns
   */
  private cleanupErrorPatterns(): void {
    const now = Date.now();
    const maxAge = 60 * 60 * 1000; // 1 hour

    // Convert to array to avoid iterator issues
    const entries = Array.from(this.errorPatterns.entries());
    for (const [key, pattern] of entries) {
      if (now - pattern.lastSeen.getTime() > maxAge) {
        this.errorPatterns.delete(key);
      }
    }
  }

  /**
   * Get current error pattern statistics (for monitoring)
   */
  getErrorPatternStats(): {
    totalClients: number;
    highRiskClients: number;
    topErrorClients: Array<{
      client: string;
      count: number;
      riskScore: number;
      lastSeen: Date;
    }>;
  } {
    const highRiskClients = Array.from(this.errorPatterns.entries()).filter(
      ([, pattern]) => pattern.riskScore >= 6,
    ).length;

    const topErrorClients = Array.from(this.errorPatterns.entries())
      .sort(([, a], [, b]) => b.count - a.count)
      .slice(0, 10)
      .map(([client, pattern]) => ({
        client: client.substring(0, 30) + '...', // Truncate for privacy
        count: pattern.count,
        riskScore: pattern.riskScore,
        lastSeen: pattern.lastSeen,
      }));

    return {
      totalClients: this.errorPatterns.size,
      highRiskClients,
      topErrorClients,
    };
  }
}

/**
 * Enterprise Rate Limiting Guard - Computer Use API Security Protection
 *
 * This guard provides comprehensive rate limiting protection for all Bytebot
 * computer-use endpoints with threat detection, IP-based tracking, and
 * configurable limits per endpoint type.
 *
 * @fileoverview Enterprise-grade rate limiting with security monitoring
 * @version 1.0.0
 * @author Input Validation & API Security Specialist
 */

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  HttpException,
  HttpStatus,
  Logger,
  SetMetadata,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ThrottlerGuard, ThrottlerException } from '@nestjs/throttler';
import { Request } from 'express';

/**
 * Rate limiting configuration per endpoint type
 */
interface RateLimitConfig {
  /** Maximum requests per time window */
  limit: number;

  /** Time window in seconds */
  windowSeconds: number;

  /** Rate limit tier (for logging/monitoring) */
  tier: 'strict' | 'moderate' | 'lenient';

  /** Custom error message */
  message?: string;
}

/**
 * Default rate limiting configurations by endpoint type
 */
const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  // Computer control operations - moderate limits
  computer_use: {
    limit: 120,
    windowSeconds: 60,
    tier: 'moderate',
    message: 'Computer control rate limit exceeded. Please slow down.',
  },

  // Authentication endpoints - strict limits
  auth: {
    limit: 10,
    windowSeconds: 60,
    tier: 'strict',
    message: 'Authentication rate limit exceeded. Try again later.',
  },

  // Screenshot/vision operations - moderate limits (resource intensive)
  vision: {
    limit: 30,
    windowSeconds: 60,
    tier: 'moderate',
    message: 'Vision processing rate limit exceeded.',
  },

  // File operations - strict limits (potential for abuse)
  file_operations: {
    limit: 20,
    windowSeconds: 60,
    tier: 'strict',
    message: 'File operation rate limit exceeded.',
  },

  // General API operations - lenient limits
  general: {
    limit: 200,
    windowSeconds: 60,
    tier: 'lenient',
    message: 'API rate limit exceeded. Please reduce request frequency.',
  },
};

/**
 * Metadata key for rate limit configuration
 */
export const RATE_LIMIT_KEY = 'rate-limit';

/**
 * Decorator to set custom rate limits for specific endpoints
 */
export const RateLimit = (
  config: Partial<RateLimitConfig> & { type: string },
) =>
  SetMetadata(RATE_LIMIT_KEY, {
    ...RATE_LIMIT_CONFIGS.general,
    ...config,
  });

@Injectable()
export class EnterpriseRateLimitGuard
  extends ThrottlerGuard
  implements CanActivate
{
  private readonly logger = new Logger(EnterpriseRateLimitGuard.name);

  // In-memory tracking for suspicious activity
  private suspiciousActivityTracker = new Map<
    string,
    {
      violations: number;
      firstViolation: Date;
      blocked: boolean;
    }
  >();

  constructor(
    options: any,
    storageService: any,
    protected reflector: Reflector,
  ) {
    super(options, storageService, reflector);
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<Request>();
    const operationId = `rate-limit-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    try {
      // Get rate limit configuration for this endpoint
      const rateLimitConfig = this.getRateLimitConfig(context);
      const clientIdentifier = this.getClientIdentifier(request);

      this.logger.debug(`[${operationId}] Rate limit check initiated`, {
        operationId,
        endpoint: request.path,
        method: request.method,
        clientIdentifier,
        rateLimitTier: rateLimitConfig.tier,
        limit: rateLimitConfig.limit,
        windowSeconds: rateLimitConfig.windowSeconds,
      });

      // Check if client is temporarily blocked for suspicious activity
      if (this.isClientBlocked(clientIdentifier)) {
        this.logger.warn(
          `[${operationId}] Client blocked due to suspicious activity`,
          {
            operationId,
            clientIdentifier,
            endpoint: request.path,
            blocked: true,
          },
        );

        throw new ThrottlerException(
          'Access temporarily blocked due to suspicious activity',
        );
      }

      // Perform rate limiting check using NestJS throttler
      const allowed = await super.canActivate(context);

      if (allowed) {
        this.logger.debug(`[${operationId}] Rate limit check passed`, {
          operationId,
          clientIdentifier,
          endpoint: request.path,
          allowed: true,
          rateLimitTier: rateLimitConfig.tier,
        });

        // Reset suspicious activity counter on successful request
        this.resetSuspiciousActivity(clientIdentifier);

        return true;
      }

      // This shouldn't be reached if super.canActivate throws on failure
      return false;
    } catch (_error) {
      if (
        _error instanceof ThrottlerException ||
        _error.status === HttpStatus.TOO_MANY_REQUESTS
      ) {
        const clientIdentifier = this.getClientIdentifier(request);
        const rateLimitConfig = this.getRateLimitConfig(context);

        // Track rate limit violations for suspicious activity detection
        this.trackSuspiciousActivity(clientIdentifier);

        this.logger.warn(`[${operationId}] Rate limit exceeded`, {
          operationId,
          clientIdentifier,
          endpoint: request.path,
          method: request.method,
          rateLimitTier: rateLimitConfig.tier,
          limit: rateLimitConfig.limit,
          userAgent: request.headers['user-agent'],
          rateLimited: true,
        });

        // Return custom error message
        throw new HttpException(
          {
            statusCode: HttpStatus.TOO_MANY_REQUESTS,
            error: 'Too Many Requests',
            message: rateLimitConfig.message || 'Rate limit exceeded',
            retryAfter: rateLimitConfig.windowSeconds,
            rateLimitTier: rateLimitConfig.tier,
            operationId,
          },
          HttpStatus.TOO_MANY_REQUESTS,
        );
      }

      // Re-throw other errors
      throw _error;
    }
  }

  /**
   * Get rate limit configuration for the current endpoint
   */
  private getRateLimitConfig(context: ExecutionContext): RateLimitConfig {
    // Try to get custom rate limit from decorator first
    const customConfig = this.reflector.getAllAndOverride<
      RateLimitConfig & { type: string }
    >(RATE_LIMIT_KEY, [context.getHandler(), context.getClass()]);

    if (customConfig) {
      return customConfig;
    }

    // Determine rate limit type based on endpoint path
    const request = context.switchToHttp().getRequest<Request>();
    const path = request.path.toLowerCase();

    if (path.includes('computer-use')) {
      return RATE_LIMIT_CONFIGS.computer_use;
    } else if (path.includes('auth') || path.includes('login')) {
      return RATE_LIMIT_CONFIGS.auth;
    } else if (
      path.includes('screenshot') ||
      path.includes('vision') ||
      path.includes('ocr')
    ) {
      return RATE_LIMIT_CONFIGS.vision;
    } else if (
      path.includes('file') ||
      path.includes('read') ||
      path.includes('write')
    ) {
      return RATE_LIMIT_CONFIGS.file_operations;
    }

    // Default to general rate limiting
    return RATE_LIMIT_CONFIGS.general;
  }

  /**
   * Generate client identifier for rate limiting
   */
  private getClientIdentifier(request: Request): string {
    // Use combination of IP and User-Agent for better identification
    const ip =
      request.ip ||
      request.connection.remoteAddress ||
      request.socket.remoteAddress ||
      (request.headers['x-forwarded-for'] as string)?.split(',')[0] ||
      'unknown';

    const userAgent = request.headers['user-agent'] || 'unknown';

    // Create hash-like identifier without actually hashing (for performance)
    return `${ip}:${userAgent.substring(0, 50)}`.replace(
      /[^a-zA-Z0-9:.-]/g,
      '_',
    );
  }

  /**
   * Track suspicious activity for potential threats
   */
  private trackSuspiciousActivity(clientIdentifier: string): void {
    const now = new Date();
    const existingEntry = this.suspiciousActivityTracker.get(clientIdentifier);

    if (existingEntry) {
      existingEntry.violations += 1;

      // Block client if too many violations within time window
      const timeDiff = now.getTime() - existingEntry.firstViolation.getTime();
      if (existingEntry.violations >= 10 && timeDiff < 300000) {
        // 5 minutes
        existingEntry.blocked = true;

        this.logger.error(
          'Client blocked for suspicious rate limit violations',
          {
            clientIdentifier,
            violations: existingEntry.violations,
            timePeriodMs: timeDiff,
            blocked: true,
          },
        );
      }
    } else {
      this.suspiciousActivityTracker.set(clientIdentifier, {
        violations: 1,
        firstViolation: now,
        blocked: false,
      });
    }

    // Clean up old entries (keep only last hour)
    this.cleanupSuspiciousActivityTracker();
  }

  /**
   * Check if client is currently blocked
   */
  private isClientBlocked(clientIdentifier: string): boolean {
    const entry = this.suspiciousActivityTracker.get(clientIdentifier);

    if (!entry) return false;

    // Unblock after 1 hour
    const blockDuration = 60 * 60 * 1000; // 1 hour
    const timeSinceFirstViolation = Date.now() - entry.firstViolation.getTime();

    if (timeSinceFirstViolation > blockDuration) {
      this.suspiciousActivityTracker.delete(clientIdentifier);
      return false;
    }

    return entry.blocked;
  }

  /**
   * Reset suspicious activity tracking for client
   */
  private resetSuspiciousActivity(clientIdentifier: string): void {
    const entry = this.suspiciousActivityTracker.get(clientIdentifier);

    if (entry && entry.violations > 0) {
      // Reset violations but keep the entry for tracking
      entry.violations = 0;
      entry.blocked = false;
    }
  }

  /**
   * Clean up old suspicious activity entries
   */
  private cleanupSuspiciousActivityTracker(): void {
    const now = Date.now();
    const maxAge = 60 * 60 * 1000; // 1 hour

    for (const [clientId, entry] of Array.from(
      this.suspiciousActivityTracker.entries(),
    )) {
      if (now - entry.firstViolation.getTime() > maxAge) {
        this.suspiciousActivityTracker.delete(clientId);
      }
    }
  }

  /**
   * Get current suspicious activity statistics (for monitoring)
   */
  getSuspiciousActivityStats(): {
    totalTracked: number;
    currentlyBlocked: number;
    topViolators: Array<{
      client: string;
      violations: number;
      blocked: boolean;
    }>;
  } {
    const blocked = Array.from(this.suspiciousActivityTracker.entries()).filter(
      ([, entry]) => entry.blocked,
    ).length;

    const topViolators = Array.from(this.suspiciousActivityTracker.entries())
      .sort(([, a], [, b]) => b.violations - a.violations)
      .slice(0, 10)
      .map(([client, entry]) => ({
        client: client.substring(0, 20) + '...', // Truncate for privacy
        violations: entry.violations,
        blocked: entry.blocked,
      }));

    return {
      totalTracked: this.suspiciousActivityTracker.size,
      currentlyBlocked: blocked,
      topViolators,
    };
  }
}

/**
 * Cache Interceptor - Intelligent API Response Caching
 *
 * Provides transparent caching for API endpoints with intelligent cache
 * strategies, conditional caching, and automatic invalidation. Designed
 * to maximize cache hit rates while maintaining data consistency.
 *
 * Features:
 * - Automatic cache key generation from request parameters
 * - Conditional caching based on response status and content
 * - TTL configuration per endpoint pattern
 * - Cache invalidation on mutations
 * - ETag and Last-Modified header support
 * - User-specific caching for personalized responses
 * - Comprehensive cache metrics and monitoring
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, tap } from 'rxjs';
import { Request, Response } from 'express';
import { CacheService } from '../../cache/cache.service';
import { CacheKeyGenerator } from '../../cache/cache-key.generator';
import { MetricsService } from '../../metrics/metrics.service';
import { createHash } from 'crypto';

/**
 * Cache configuration for different endpoint patterns
 */
interface CacheRule {
  pattern: RegExp;
  ttl: number; // Time to live in seconds
  varyBy?: string[]; // Request headers/params to vary cache by
  includeUserId?: boolean; // Include user ID in cache key
  cacheableStatuses?: number[]; // HTTP status codes that should be cached
  skipCacheIf?: (_req: Request, res: Response) => boolean; // Dynamic cache skipping
}

/**
 * Cache metadata stored with cached responses
 */
interface CacheMetadata {
  timestamp: number;
  etag?: string;
  lastModified?: string;
  userId?: string;
  ttl: number;
  url: string;
  method: string;
}

/**
 * Cached response data structure
 */
interface CachedResponse {
  data: unknown;
  metadata: CacheMetadata;
  headers: Record<string, string>;
}

/**
 * Cache statistics for monitoring
 */
interface CacheInterceptorStats {
  totalRequests: number;
  cacheHits: number;
  cacheMisses: number;
  cacheSkips: number;
  hitRate: number;
  averageResponseTime: number;
  endpointStats: Map<
    string,
    {
      hits: number;
      misses: number;
      hitRate: number;
    }
  >;
}

/**
 * Cache interceptor for API response caching
 */
@Injectable()
export class CacheInterceptor implements NestInterceptor {
  private readonly logger = new Logger(CacheInterceptor.name);
  private readonly stats: CacheInterceptorStats = {
    totalRequests: 0,
    cacheHits: 0,
    cacheMisses: 0,
    cacheSkips: 0,
    hitRate: 0,
    averageResponseTime: 0,
    endpointStats: new Map(),
  };

  // Default cache rules for different endpoint patterns
  private readonly cacheRules: CacheRule[] = [
    // Task data - cache for 5 minutes
    {
      pattern: /^\/api\/tasks\/[^/]+$/,
      ttl: 300,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
    },

    // Task lists - cache for 2 minutes
    {
      pattern: /^\/api\/tasks(\?.*)?$/,
      ttl: 120,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
      skipCacheIf: (_req) => {
        // Skip cache if real-time data is requested
        return req.query.realtime === 'true';
      },
    },

    // Task messages - cache for 10 minutes
    {
      pattern: /^\/api\/tasks\/[^/]+\/messages/,
      ttl: 600,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
    },

    // Static data - cache for 1 hour
    {
      pattern: /^\/api\/models$/,
      ttl: 3600,
      cacheableStatuses: [200],
    },

    // Computer-use screenshots - cache for 30 seconds
    {
      pattern: /^\/computer-use$/,
      ttl: 30,
      cacheableStatuses: [200],
      skipCacheIf: (_req) => {
        // Only cache screenshot requests
        return req.body?.action !== 'screenshot';
      },
    },

    // Health checks - cache for 1 minute
    {
      pattern: /^\/health/,
      ttl: 60,
      cacheableStatuses: [200],
    },
  ];

  constructor(
    private readonly cacheService: CacheService,
    private readonly keyGenerator: CacheKeyGenerator,
    private readonly metricsService?: MetricsService,
  ) {
    this.logger.log('Cache Interceptor initialized');
    this.logger.log(`Configured ${this.cacheRules.length} cache rules`);

    // Start periodic stats reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept HTTP requests to implement caching
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    // Only cache GET requests by default
    if (request.method !== 'GET') {
      // For non-GET requests, invalidate related cache entries
      this.invalidateRelatedCache(request);
      return next.handle();
    }

    const operationId =
      (request as Request & { operationId?: string }).operationId ||
      `cache_${Date.now()}`;
    const startTime = Date.now();

    // Find applicable cache rule
    const cacheRule = this.findCacheRule(request);
    if (!cacheRule) {
      this.stats.cacheSkips++;
      this.updateStats();
      return next.handle();
    }

    // Check if caching should be skipped
    if (cacheRule.skipCacheIf?.(request, response)) {
      this.stats.cacheSkips++;
      this.updateStats();
      return next.handle();
    }

    // Generate cache key
    const cacheKey = this.generateCacheKey(request, cacheRule);

    return this.handleCachedRequest(
      cacheKey,
      cacheRule,
      request,
      response,
      next,
      operationId,
      startTime,
    );
  }

  /**
   * Handle request with caching logic
   */
  private handleCachedRequest(
    cacheKey: string,
    cacheRule: CacheRule,
    request: Request,
    response: Response,
    next: CallHandler,
    operationId: string,
    startTime: number,
  ): Observable<unknown> {
    return new Observable((observer) => {
      // Try to get from cache first
      this.cacheService
        .get<CachedResponse>(cacheKey)
        .then((cachedResponse) => {
          if (cachedResponse && this.isCacheValid(cachedResponse, request)) {
            // Cache hit - return cached response
            this.handleCacheHit(
              cachedResponse,
              response,
              operationId,
              startTime,
            );
            observer.next(cachedResponse.data);
            observer.complete();
          } else {
            // Cache miss - execute request and cache result
            this.handleCacheMiss(
              cacheKey,
              cacheRule,
              request,
              response,
              next,
              operationId,
              startTime,
            ).subscribe({
              next: (data) => {
                observer.next(data);
              },
              error: (_error) => {
                observer.error(_error);
              },
              complete: () => {
                observer.complete();
              },
            });
          }
        })
        .catch((_error) => {
          // Cache error - proceed without cache
          this.logger.error(
            `[${operationId}] Cache retrieval error: ${error instanceof Error ? _error.message : 'Unknown error'}`,
          );

          next.handle().subscribe({
            next: (data) => observer.next(data),
            error: (_error) => observer.error(_error),
            complete: () => observer.complete(),
          });
        });
    });
  }

  /**
   * Handle cache hit scenario
   */
  private handleCacheHit(
    cachedResponse: CachedResponse,
    response: Response,
    operationId: string,
    startTime: number,
  ): void {
    const duration = Date.now() - startTime;

    // Set cached headers
    Object.entries(cachedResponse.headers).forEach(([key, value]) => {
      response.set(key, value);
    });

    // Add cache headers
    response.set('X-Cache', 'HIT');
    response.set('X-Cache-Key', this.hashForLogging(operationId));

    this.stats.cacheHits++;
    this.recordEndpointStats(cachedResponse.metadata.url, 'hit');

    this.logger.debug(
      `[${operationId}] Cache HIT: ${cachedResponse.metadata.url} (${duration}ms)`,
      {
        cacheAge: Date.now() - cachedResponse.metadata.timestamp,
        ttl: cachedResponse.metadata.ttl,
      },
    );

    // Record metrics
    if (this.metricsService) {
      this.metricsService.recordCacheOperation?.('get', 'hit', duration);
    }

    this.updateStats();
  }

  /**
   * Handle cache miss scenario
   */
  private handleCacheMiss(
    cacheKey: string,
    cacheRule: CacheRule,
    request: Request,
    response: Response,
    next: CallHandler,
    operationId: string,
    startTime: number,
  ): Observable<unknown> {
    return next.handle().pipe(
      tap(async (data) => {
        const duration = Date.now() - startTime;

        this.stats.cacheMisses++;
        this.recordEndpointStats(request.url, 'miss');

        // Check if response should be cached
        if (this.shouldCacheResponse(response, cacheRule)) {
          // Create cached response
          const cachedResponse: CachedResponse = {
            data,
            metadata: {
              timestamp: Date.now(),
              etag: response.get('ETag'),
              lastModified: response.get('Last-Modified'),
              userId: this.extractUserId(request),
              ttl: cacheRule.ttl,
              url: request.url,
              method: request.method,
            },
            headers: this.extractCacheableHeaders(response),
          };

          // Store in cache
          await this.cacheService.set(cacheKey, cachedResponse, {
            ttl: cacheRule.ttl,
            namespace: 'api-cache',
          });

          this.logger.debug(
            `[${operationId}] Cache MISS: ${request.url} - stored for ${cacheRule.ttl}s (${duration}ms)`,
          );
        } else {
          this.logger.debug(
            `[${operationId}] Cache SKIP: ${request.url} - not cacheable (${duration}ms)`,
          );
        }

        // Add cache headers
        response.set('X-Cache', 'MISS');
        response.set('X-Cache-Key', this.hashForLogging(operationId));

        // Record metrics
        if (this.metricsService) {
          this.metricsService.recordCacheOperation?.('get', 'miss', duration);
        }

        this.updateStats();
      }),
    );
  }

  /**
   * Find applicable cache rule for request
   */
  private findCacheRule(request: Request): CacheRule | null {
    const path = request.url.split('?')[0]; // Remove query string for pattern matching

    for (const rule of this.cacheRules) {
      if (rule.pattern.test(path)) {
        return rule;
      }
    }

    return null;
  }

  /**
   * Generate cache key for request
   */
  private generateCacheKey(request: Request, cacheRule: CacheRule): string {
    const keyParts: string[] = [request.method, request.url];

    // Add user ID if required
    if (cacheRule.includeUserId) {
      const userId = this.extractUserId(request);
      if (userId) {
        keyParts.push(`user:${userId}`);
      }
    }

    // Add vary-by headers
    if (cacheRule.varyBy) {
      for (const header of cacheRule.varyBy) {
        const value = request.get(header);
        if (value) {
          keyParts.push(`${header}:${this.hashString(value)}`);
        }
      }
    }

    return this.keyGenerator.generateApiKey(
      request.method,
      request.url,
      request.query,
      cacheRule.includeUserId ? this.extractUserId(request) : undefined,
    );
  }

  /**
   * Check if cached response is still valid
   */
  private isCacheValid(
    cachedResponse: CachedResponse,
    request: Request,
  ): boolean {
    const now = Date.now();
    const cacheAge = (now - cachedResponse.metadata.timestamp) / 1000;

    // Check TTL expiration
    if (cacheAge > cachedResponse.metadata.ttl) {
      return false;
    }

    // Check ETag if provided in request
    const ifNoneMatch = request.get('If-None-Match');
    if (ifNoneMatch && cachedResponse.metadata.etag) {
      return ifNoneMatch === cachedResponse.metadata.etag;
    }

    // Check Last-Modified if provided in request
    const ifModifiedSince = request.get('If-Modified-Since');
    if (ifModifiedSince && cachedResponse.metadata.lastModified) {
      const modifiedSince = new Date(ifModifiedSince);
      const lastModified = new Date(cachedResponse.metadata.lastModified);
      return lastModified <= modifiedSince;
    }

    return true;
  }

  /**
   * Check if response should be cached
   */
  private shouldCacheResponse(
    response: Response,
    cacheRule: CacheRule,
  ): boolean {
    // Check status code
    if (
      cacheRule.cacheableStatuses &&
      !cacheRule.cacheableStatuses.includes(response.statusCode)
    ) {
      return false;
    }

    // Check for cache-control directives
    const cacheControl = response.get('Cache-Control');
    if (cacheControl) {
      if (
        cacheControl.includes('no-store') ||
        cacheControl.includes('private')
      ) {
        return false;
      }
    }

    return true;
  }

  /**
   * Extract user ID from request for user-specific caching
   */
  private extractUserId(request: Request): string | undefined {
    // Try to extract from various common locations
    const authHeader = request.get('Authorization');
    if (authHeader) {
      // Simple hash of auth header for user identification
      return this.hashString(authHeader).substring(0, 8);
    }

    // Try session or other user identification methods
    // This would be implemented based on the app's authentication strategy
    return undefined;
  }

  /**
   * Extract cacheable headers from response
   */
  private extractCacheableHeaders(response: Response): Record<string, string> {
    const cacheableHeaders = [
      'Content-Type',
      'ETag',
      'Last-Modified',
      'Expires',
      'Cache-Control',
    ];

    const headers: Record<string, string> = {};

    for (const header of cacheableHeaders) {
      const value = response.get(header);
      if (value) {
        headers[header] = value;
      }
    }

    return headers;
  }

  /**
   * Invalidate cache entries related to a mutation request
   */
  private async invalidateRelatedCache(request: Request): Promise<void> {
    try {
      // Extract resource pattern for invalidation
      const resourcePattern = this.extractResourcePattern(request);
      if (resourcePattern) {
        await this.cacheService.invalidatePattern(resourcePattern, 'api-cache');

        this.logger.debug(
          `Cache invalidation triggered by ${request.method} ${request.url}`,
          { pattern: resourcePattern },
        );
      }
    } catch (_error) {
      this.logger.error(
        `Cache invalidation _error: ${_error instanceof Error ? __error.message : 'Unknown _error'}`,
      );
    }
  }

  /**
   * Extract resource pattern for cache invalidation
   */
  private extractResourcePattern(request: Request): string | null {
    // Task operations - invalidate task-related cache
    if (request.url.match(/^\/api\/tasks/)) {
      const taskId = request.url.match(/\/api\/tasks\/([^/]+)/)?.[1];
      if (taskId) {
        return `api:*:tasks:${taskId}*`;
      } else {
        return 'api:*:tasks*';
      }
    }

    return null;
  }

  /**
   * Hash string for consistent identification
   */
  private hashString(input: string): string {
    return createHash('md5').update(input).digest('hex');
  }

  /**
   * Create safe hash for logging
   */
  private hashForLogging(input: string): string {
    return createHash('md5').update(input).digest('hex').substring(0, 8);
  }

  /**
   * Record endpoint-specific cache statistics
   */
  private recordEndpointStats(url: string, result: 'hit' | 'miss'): void {
    const normalizedUrl = this.normalizeUrlForStats(url);

    if (!this.stats.endpointStats.has(normalizedUrl)) {
      this.stats.endpointStats.set(normalizedUrl, {
        hits: 0,
        misses: 0,
        hitRate: 0,
      });
    }

    const endpointStats = this.stats.endpointStats.get(normalizedUrl)!;

    if (result === 'hit') {
      endpointStats.hits++;
    } else {
      endpointStats.misses++;
    }

    const total = endpointStats.hits + endpointStats.misses;
    endpointStats.hitRate = total > 0 ? (endpointStats.hits / total) * 100 : 0;
  }

  /**
   * Normalize URL for statistics grouping
   */
  private normalizeUrlForStats(url: string): string {
    return url
      .split('?')[0] // Remove query string
      .replace(/\/\d+/g, '/:id') // Replace IDs
      .replace(/\/[a-f0-9-]{36}/g, '/:uuid'); // Replace UUIDs
  }

  /**
   * Update overall cache statistics
   */
  private updateStats(): void {
    this.stats.totalRequests =
      this.stats.cacheHits + this.stats.cacheMisses + this.stats.cacheSkips;

    if (this.stats.totalRequests > 0) {
      this.stats.hitRate =
        (this.stats.cacheHits / this.stats.totalRequests) * 100;
    }
  }

  /**
   * Get current cache statistics
   */
  getStats(): CacheInterceptorStats {
    return {
      ...this.stats,
      endpointStats: new Map(this.stats.endpointStats),
    };
  }

  /**
   * Clear cache statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalRequests: 0,
      cacheHits: 0,
      cacheMisses: 0,
      cacheSkips: 0,
      hitRate: 0,
      averageResponseTime: 0,
    });

    this.stats.endpointStats.clear();
    this.logger.log('Cache interceptor statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report cache stats every 5 minutes
    setInterval(() => {
      if (this.stats.totalRequests > 0) {
        this.logger.log('Cache Interceptor Statistics:', {
          totalRequests: this.stats.totalRequests,
          cacheHits: this.stats.cacheHits,
          cacheMisses: this.stats.cacheMisses,
          cacheSkips: this.stats.cacheSkips,
          hitRate: `${this.stats.hitRate.toFixed(1)}%`,
          topEndpoints: Array.from(this.stats.endpointStats.entries())
            .sort((a, b) => b[1].hits + b[1].misses - (a[1].hits + a[1].misses))
            .slice(0, 5)
            .map(([url, stats]) => ({
              url,
              requests: stats.hits + stats.misses,
              hitRate: `${stats.hitRate.toFixed(1)}%`,
            })),
        });
      }
    }, 300000); // 5 minutes
  }
}

/**
 * Compression Interceptor - Response Compression for Performance
 *
 * Provides intelligent response compression with support for multiple
 * compression algorithms (gzip, brotli, deflate). Automatically selects
 * optimal compression based on content type, size, and client support.
 *
 * Features:
 * - Multi-algorithm support (gzip, brotli, deflate)
 * - Content-type specific compression rules
 * - Minimum size thresholds for efficiency
 * - Client capability detection
 * - Compression ratio metrics
 * - Performance impact monitoring
 * - Configurable compression levels
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, map } from 'rxjs';
import { Request, Response } from 'express';
import { gzip, brotliCompress, deflate } from 'zlib';
import { promisify } from 'util';
import { MetricsService } from '../../metrics/metrics.service';

// Promisify compression functions
const gzipAsync = promisify(gzip);
const brotliCompressAsync = promisify(brotliCompress);
const deflateAsync = promisify(deflate);

/**
 * Compression algorithm types
 */
type CompressionAlgorithm = 'gzip' | 'brotli' | 'deflate' | 'identity';

/**
 * Compression configuration
 */
interface CompressionConfig {
  minSize: number; // Minimum response size to compress (bytes)
  level: number; // Compression level (1-9 for gzip/deflate, 1-11 for brotli)
  threshold: number; // Minimum compression ratio to use compression
  compressibleTypes: Set<string>; // Content types that should be compressed
  maxSize: number; // Maximum response size to compress (bytes)
}

/**
 * Compression statistics
 */
interface CompressionStats {
  totalRequests: number;
  compressedRequests: number;
  compressionRatio: number;
  bytesOriginal: number;
  bytesCompressed: number;
  averageCompressionTime: number;
  algorithmUsage: Record<CompressionAlgorithm, number>;
}

/**
 * Compression result for a single response
 */
interface CompressionResult {
  algorithm: CompressionAlgorithm;
  originalSize: number;
  compressedSize: number;
  ratio: number;
  compressionTime: number;
  applied: boolean;
}

/**
 * Response compression interceptor
 */
@Injectable()
export class CompressionInterceptor implements NestInterceptor {
  private readonly logger = new Logger(CompressionInterceptor.name);
  private readonly stats: CompressionStats = {
    totalRequests: 0,
    compressedRequests: 0,
    compressionRatio: 0,
    bytesOriginal: 0,
    bytesCompressed: 0,
    averageCompressionTime: 0,
    algorithmUsage: {
      gzip: 0,
      brotli: 0,
      deflate: 0,
      identity: 0,
    },
  };

  // Compression configuration (configurable via environment variables)
  private readonly config: CompressionConfig = {
    minSize: parseInt(process.env.COMPRESSION_MIN_SIZE || '1024', 10), // 1KB
    level: parseInt(process.env.COMPRESSION_LEVEL || '6', 10), // Balanced compression
    threshold: parseFloat(process.env.COMPRESSION_THRESHOLD || '0.8'), // 20% minimum reduction
    maxSize: parseInt(process.env.COMPRESSION_MAX_SIZE || '10485760', 10), // 10MB
    compressibleTypes: new Set([
      'application/json',
      'application/javascript',
      'application/xml',
      'text/plain',
      'text/html',
      'text/css',
      'text/javascript',
      'text/xml',
      'image/svg+xml',
    ]),
  };

  constructor(private readonly metricsService?: MetricsService) {
    this.logger.log('Compression Interceptor initialized');
    this.logger.log(
      `Config: minSize=${this.config.minSize}b, level=${this.config.level}, threshold=${this.config.threshold}`,
    );

    // Start periodic stats reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept HTTP responses to apply compression
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    return next.handle().pipe(
      map(async (data) => {
        // Skip compression if already handled by middleware
        if (response.get('Content-Encoding')) {
          this.updateStats({
            algorithm: 'identity',
            originalSize: 0,
            compressedSize: 0,
            ratio: 1,
            compressionTime: 0,
            applied: false,
          });
          return data;
        }

        // Compress response if applicable
        const compressionResult = await this.compressResponse(
          data,
          request,
          response,
        );

        if (
          compressionResult.applied &&
          compressionResult.algorithm !== 'identity'
        ) {
          // Set compression headers
          response.set('Content-Encoding', compressionResult.algorithm);
          response.set('Vary', 'Accept-Encoding');

          this.logger.debug(
            `Response compressed: ${compressionResult.algorithm}, ` +
              `${compressionResult.originalSize}b → ${compressionResult.compressedSize}b ` +
              `(${(compressionResult.ratio * 100).toFixed(1)}% reduction)`,
          );
        }

        this.updateStats(compressionResult);
        return data;
      }),
    );
  }

  /**
   * Compress response data with optimal algorithm selection
   */
  private async compressResponse(
    data: unknown,
    request: Request,
    response: Response,
  ): Promise<CompressionResult> {
    const operationId =
      (request as Request & { operationId?: string }).operationId ||
      `compress_${Date.now()}`;
    const startTime = Date.now();

    try {
      // Convert data to buffer for processing
      const responseBuffer = this.dataToBuffer(data);
      const originalSize = responseBuffer.length;

      // Check if compression should be applied
      if (!this.shouldCompress(responseBuffer, response)) {
        return {
          algorithm: 'identity',
          originalSize,
          compressedSize: originalSize,
          ratio: 1,
          compressionTime: 0,
          applied: false,
        };
      }

      // Determine best compression algorithm
      const algorithm = this.selectCompressionAlgorithm(request);

      // Apply compression
      const compressedData = await this.applyCompression(
        responseBuffer,
        algorithm,
      );
      const compressedSize = compressedData.length;
      const ratio = compressedSize / originalSize;

      // Check if compression is beneficial
      if (ratio > this.config.threshold) {
        // Compression not beneficial enough
        return {
          algorithm: 'identity',
          originalSize,
          compressedSize: originalSize,
          ratio: 1,
          compressionTime: Date.now() - startTime,
          applied: false,
        };
      }

      // Set compressed data as response
      response.send(compressedData);

      return {
        algorithm,
        originalSize,
        compressedSize,
        ratio,
        compressionTime: Date.now() - startTime,
        applied: true,
      };
    } catch (_error) {
      const compressionTime = Date.now() - startTime;
      const errorMessage =
        _error instanceof Error ? __error.message : 'Unknown _error';

      this.logger.error(
        `[${operationId}] Compression failed: ${errorMessage} (${compressionTime}ms)`,
      );

      // Return uncompressed data on error
      return {
        algorithm: 'identity',
        originalSize: this.dataToBuffer(data).length,
        compressedSize: this.dataToBuffer(data).length,
        ratio: 1,
        compressionTime,
        applied: false,
      };
    }
  }

  /**
   * Determine if response should be compressed
   */
  private shouldCompress(data: Buffer, response: Response): boolean {
    // Check minimum size
    if (data.length < this.config.minSize) {
      return false;
    }

    // Check maximum size
    if (data.length > this.config.maxSize) {
      return false;
    }

    // Check content type
    const contentType = response.get('Content-Type') || '';
    const baseType = contentType.split(';')[0].toLowerCase();

    return this.config.compressibleTypes.has(baseType);
  }

  /**
   * Select optimal compression algorithm based on client support
   */
  private selectCompressionAlgorithm(request: Request): CompressionAlgorithm {
    const acceptEncoding = request.get('Accept-Encoding') || '';

    // Priority order: brotli (best compression) → gzip (widely supported) → deflate
    if (acceptEncoding.includes('br')) {
      return 'brotli';
    } else if (acceptEncoding.includes('gzip')) {
      return 'gzip';
    } else if (acceptEncoding.includes('deflate')) {
      return 'deflate';
    } else {
      return 'identity';
    }
  }

  /**
   * Apply compression using specified algorithm
   */
  private async applyCompression(
    data: Buffer,
    algorithm: CompressionAlgorithm,
  ): Promise<Buffer> {
    switch (algorithm) {
      case 'brotli':
        return await brotliCompressAsync(data, {
          params: {
            [require('zlib').constants.BROTLI_PARAM_QUALITY]: this.config.level,
          },
        });

      case 'gzip':
        return await gzipAsync(data, { level: this.config.level });

      case 'deflate':
        return await deflateAsync(data, { level: this.config.level });

      default:
        return data;
    }
  }

  /**
   * Convert response data to buffer
   */
  private dataToBuffer(data: unknown): Buffer {
    if (Buffer.isBuffer(data)) {
      return data;
    }

    if (typeof data === 'string') {
      return Buffer.from(data, 'utf8');
    }

    if (typeof data === 'object') {
      return Buffer.from(JSON.stringify(data), 'utf8');
    }

    return Buffer.from(String(data), 'utf8');
  }

  /**
   * Update compression statistics
   */
  private updateStats(result: CompressionResult): void {
    try {
      this.stats.totalRequests++;

      if (result.applied && result.algorithm !== 'identity') {
        this.stats.compressedRequests++;
        this.stats.bytesOriginal += result.originalSize;
        this.stats.bytesCompressed += result.compressedSize;

        // Update average compression time
        this.stats.averageCompressionTime =
          (this.stats.averageCompressionTime *
            (this.stats.compressedRequests - 1) +
            result.compressionTime) /
          this.stats.compressedRequests;
      } else {
        this.stats.bytesOriginal += result.originalSize;
        this.stats.bytesCompressed += result.originalSize; // No compression applied
      }

      // Update algorithm usage
      this.stats.algorithmUsage[result.algorithm]++;

      // Calculate overall compression ratio
      if (this.stats.bytesOriginal > 0) {
        this.stats.compressionRatio =
          (this.stats.bytesOriginal - this.stats.bytesCompressed) /
          this.stats.bytesOriginal;
      }

      // Record metrics
      if (this.metricsService) {
        this.metricsService.recordCompressionMetrics?.(
          result.algorithm,
          result.originalSize,
          result.compressedSize,
          result.compressionTime,
        );
      }
    } catch (_error) {
      this.logger.error(
        `Failed to update compression statistics: ${_error instanceof Error ? __error.message : 'Unknown _error'}`,
      );
    }
  }

  /**
   * Get current compression statistics
   */
  getStats(): CompressionStats {
    return {
      ...this.stats,
      algorithmUsage: { ...this.stats.algorithmUsage },
    };
  }

  /**
   * Clear compression statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalRequests: 0,
      compressedRequests: 0,
      compressionRatio: 0,
      bytesOriginal: 0,
      bytesCompressed: 0,
      averageCompressionTime: 0,
      algorithmUsage: {
        gzip: 0,
        brotli: 0,
        deflate: 0,
        identity: 0,
      },
    });

    this.logger.log('Compression statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report compression stats every 10 minutes
    setInterval(() => {
      if (this.stats.totalRequests > 0) {
        this.logger.log('Compression Statistics Summary:', {
          totalRequests: this.stats.totalRequests,
          compressedRequests: this.stats.compressedRequests,
          compressionRate: `${((this.stats.compressedRequests / this.stats.totalRequests) * 100).toFixed(1)}%`,
          overallCompressionRatio: `${(this.stats.compressionRatio * 100).toFixed(1)}%`,
          bytesSaved: `${((this.stats.bytesOriginal - this.stats.bytesCompressed) / 1024 / 1024).toFixed(2)}MB`,
          averageCompressionTime: `${this.stats.averageCompressionTime.toFixed(2)}ms`,
          algorithmUsage: this.stats.algorithmUsage,
        });
      }
    }, 600000); // 10 minutes
  }
}

/**
 * Database Performance Interceptor - Query Monitoring and Optimization
 *
 * Provides comprehensive database query performance monitoring with
 * automatic slow query detection, query caching, and optimization
 * recommendations. Designed for enterprise database performance.
 *
 * Features:
 * - Database query performance tracking
 * - Slow query detection and alerting
 * - Query result caching with intelligent invalidation
 * - Database connection pool monitoring
 * - Query execution plan analysis
 * - Automatic retry logic for failed queries
 * - Comprehensive database metrics
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, tap, catchError } from 'rxjs';
import { Request } from 'express';
import { MetricsService } from '../../metrics/metrics.service';
import { CacheService } from '../../cache/cache.service';
import { CacheKeyGenerator } from '../../cache/cache-key.generator';

/**
 * Database operation metadata
 */
interface DatabaseOperation {
  operation: string;
  table: string;
  query?: string;
  params?: Record<string, unknown>;
  executionPlan?: Record<string, unknown>;
}

/**
 * Database performance metrics for a single query
 */
interface DatabasePerformanceMetrics {
  operationId: string;
  operation: DatabaseOperation;
  startTime: number;
  endTime: number;
  duration: number;
  resultCount?: number;
  cacheHit?: boolean;
  connectionId?: string;
  error?: Error;
}

/**
 * Database performance statistics
 */
interface DatabaseStats {
  totalQueries: number;
  averageQueryTime: number;
  slowQueries: number;
  failedQueries: number;
  cacheHitRate: number;
  connectionPoolStats: {
    active: number;
    idle: number;
    total: number;
  };
  topSlowQueries: Array<{
    operation: string;
    table: string;
    avgDuration: number;
    count: number;
  }>;
}

/**
 * Database performance configuration
 */
interface DatabaseConfig {
  slowQueryThreshold: number; // milliseconds
  criticalQueryThreshold: number; // milliseconds
  enableQueryCaching: boolean;
  defaultCacheTtl: number; // seconds
  maxRetryAttempts: number;
  retryDelay: number; // milliseconds
}

/**
 * Database performance interceptor
 */
@Injectable()
export class DatabaseInterceptor implements NestInterceptor {
  private readonly logger = new Logger(DatabaseInterceptor.name);
  private readonly stats: DatabaseStats = {
    totalQueries: 0,
    averageQueryTime: 0,
    slowQueries: 0,
    failedQueries: 0,
    cacheHitRate: 0,
    connectionPoolStats: {
      active: 0,
      idle: 0,
      total: 0,
    },
    topSlowQueries: [],
  };

  private readonly slowQueries = new Map<
    string,
    {
      totalDuration: number;
      count: number;
      avgDuration: number;
    }
  >();

  // Database performance configuration
  private readonly config: DatabaseConfig = {
    slowQueryThreshold: parseInt(
      process.env.DB_SLOW_QUERY_THRESHOLD || '1000',
      10,
    ), // 1 second
    criticalQueryThreshold: parseInt(
      process.env.DB_CRITICAL_QUERY_THRESHOLD || '5000',
      10,
    ), // 5 seconds
    enableQueryCaching: process.env.DB_ENABLE_QUERY_CACHING !== 'false',
    defaultCacheTtl: parseInt(process.env.DB_CACHE_TTL || '300', 10), // 5 minutes
    maxRetryAttempts: parseInt(process.env.DB_MAX_RETRY_ATTEMPTS || '3', 10),
    retryDelay: parseInt(process.env.DB_RETRY_DELAY || '1000', 10), // 1 second
  };

  constructor(
    private readonly metricsService?: MetricsService,
    private readonly cacheService?: CacheService,
    private readonly keyGenerator?: CacheKeyGenerator,
  ) {
    this.logger.log('Database Performance Interceptor initialized');
    this.logger.log(
      `Config: slowQuery=${this.config.slowQueryThreshold}ms, caching=${this.config.enableQueryCaching}`,
    );

    // Start periodic reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept database operations for performance monitoring
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    const operationId = request.operationId || `db_${Date.now()}`;

    // Extract database operation metadata
    const dbOperation = this.extractDatabaseOperation(context, request);
    if (!dbOperation) {
      return next.handle(); // Not a database operation
    }

    const startTime = Date.now();

    // Check cache first if caching is enabled
    if (
      this.config.enableQueryCaching &&
      this.isCacheableOperation(dbOperation)
    ) {
      return this.handleCachedDatabaseOperation(
        operationId,
        dbOperation,
        startTime,
        next,
      );
    }

    return this.handleDatabaseOperation(
      operationId,
      dbOperation,
      startTime,
      next,
    );
  }

  /**
   * Handle database operation with performance monitoring
   */
  private handleDatabaseOperation(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    next: CallHandler,
  ): Observable<unknown> {
    this.logger.debug(
      `[${operationId}] Database operation: ${dbOperation.operation} on ${dbOperation.table}`,
    );

    return next.handle().pipe(
      tap((result) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          resultCount: this.getResultCount(result),
        });
      }),
      catchError((_error) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          error,
        });
        throw error;
      }),
    );
  }

  /**
   * Handle cached database operation
   */
  private handleCachedDatabaseOperation(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    next: CallHandler,
  ): Observable<unknown> {
    if (!this.cacheService || !this.keyGenerator) {
      return this.handleDatabaseOperation(
        operationId,
        dbOperation,
        startTime,
        next,
      );
    }

    return new Observable((observer) => {
      const cacheKey = this.generateQueryCacheKey(dbOperation);

      this.cacheService
        .get(cacheKey)
        .then((cachedResult) => {
          if (cachedResult !== null) {
            // Cache hit
            this.recordDatabaseMetrics({
              operationId,
              operation: dbOperation,
              startTime,
              endTime: Date.now(),
              duration: Date.now() - startTime,
              cacheHit: true,
              resultCount: this.getResultCount(cachedResult),
            });

            this.logger.debug(
              `[${operationId}] Database cache HIT: ${dbOperation.operation}`,
            );

            observer.next(cachedResult);
            observer.complete();
          } else {
            // Cache miss - execute query and cache result
            this.handleDatabaseOperationWithCaching(
              operationId,
              dbOperation,
              startTime,
              cacheKey,
              next,
            ).subscribe({
              next: (result) => observer.next(result),
              error: (_error) => observer.error(_error),
              complete: () => observer.complete(),
            });
          }
        })
        .catch((_error) => {
          this.logger.error(
            `[${operationId}] Cache error, falling back to database: ${_error.message}`,
          );

          this.handleDatabaseOperation(
            operationId,
            dbOperation,
            startTime,
            next,
          ).subscribe({
            next: (result) => observer.next(result),
            error: (_error) => observer.error(_error),
            complete: () => observer.complete(),
          });
        });
    });
  }

  /**
   * Handle database operation with result caching
   */
  private handleDatabaseOperationWithCaching(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    cacheKey: string,
    next: CallHandler,
  ): Observable<unknown> {
    return next.handle().pipe(
      tap(async (result) => {
        const duration = Date.now() - startTime;

        // Cache the result
        if (this.cacheService) {
          await this.cacheService.set(cacheKey, result, {
            ttl: this.config.defaultCacheTtl,
            namespace: 'database-queries',
          });
        }

        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration,
          cacheHit: false,
          resultCount: this.getResultCount(result),
        });

        this.logger.debug(
          `[${operationId}] Database cache MISS: ${dbOperation.operation} - cached result (${duration}ms)`,
        );
      }),
      catchError((_error) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          error,
        });
        throw error;
      }),
    );
  }

  /**
   * Extract database operation from context
   */
  private extractDatabaseOperation(
    context: ExecutionContext,
    _request: Request,
  ): DatabaseOperation | null {
    // This would need to be customized based on the ORM/database library used
    // For Prisma, we might extract from the handler name or method metadata

    const handlerName = context.getHandler().name;
    const controllerClass = context.getClass().name;

    // Example patterns for different operations
    if (handlerName.includes('find') || handlerName.includes('get')) {
      return {
        operation: 'SELECT',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('create') || handlerName.includes('insert')) {
      return {
        operation: 'INSERT',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('update')) {
      return {
        operation: 'UPDATE',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('delete') || handlerName.includes('remove')) {
      return {
        operation: 'DELETE',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    return null; // Not a database operation
  }

  /**
   * Extract table name from controller class name
   */
  private extractTableName(controllerClass: string): string {
    // Remove 'Controller' suffix and convert to lowercase
    return controllerClass
      .replace(/Controller$/i, '')
      .toLowerCase()
      .replace(/s$/, ''); // Remove plural 's' if present
  }

  /**
   * Check if operation is cacheable
   */
  private isCacheableOperation(dbOperation: DatabaseOperation): boolean {
    // Only cache read operations
    return ['SELECT', 'FIND', 'GET'].includes(
      dbOperation.operation.toUpperCase(),
    );
  }

  /**
   * Generate cache key for database query
   */
  private generateQueryCacheKey(dbOperation: DatabaseOperation): string {
    if (!this.keyGenerator) {
      return `db:${dbOperation.operation}:${dbOperation.table}:${Date.now()}`;
    }

    return this.keyGenerator.generateDbKey(
      dbOperation.table,
      dbOperation.operation,
      dbOperation.params,
    );
  }

  /**
   * Get result count from query result
   */
  private getResultCount(result: unknown): number | undefined {
    if (result === null || result === undefined) {
      return 0;
    }

    if (Array.isArray(result)) {
      return result.length;
    }

    if (typeof result === 'object' && result !== null && 'count' in result) {
      return (result as { count: number }).count;
    }

    return 1; // Single result
  }

  /**
   * Record database performance metrics
   */
  private recordDatabaseMetrics(metrics: DatabasePerformanceMetrics): void {
    try {
      const { operation, duration, error, cacheHit } = metrics;

      // Update internal statistics
      this.stats.totalQueries++;

      if (error) {
        this.stats.failedQueries++;
        this.logger.error(
          `[${metrics.operationId}] Database operation failed: ${error.message}`,
          { operation: operation.operation, table: operation.table, duration },
        );
      } else {
        // Update average query time
        this.stats.averageQueryTime =
          (this.stats.averageQueryTime * (this.stats.totalQueries - 1) +
            duration) /
          this.stats.totalQueries;

        // Check for slow queries
        if (duration >= this.config.slowQueryThreshold) {
          this.stats.slowQueries++;
          this.recordSlowQuery(operation, duration);

          const logLevel =
            duration >= this.config.criticalQueryThreshold ? 'error' : 'warn';
          this.logger[logLevel](
            `[${metrics.operationId}] Slow database query detected: ${duration}ms`,
            { operation: operation.operation, table: operation.table },
          );
        }

        this.logger.debug(
          `[${metrics.operationId}] Database operation completed: ${operation.operation} (${duration}ms)`,
          {
            table: operation.table,
            resultCount: metrics.resultCount,
            cacheHit: cacheHit || false,
          },
        );
      }

      // Record metrics with MetricsService
      if (this.metricsService) {
        if (error) {
          this.metricsService.recordDatabaseError(
            operation.operation,
            error.constructor.name,
          );
        } else {
          this.metricsService.recordDatabaseQuery(
            operation.operation,
            operation.table,
            duration,
          );
        }
      }

      // Update cache hit rate
      if (cacheHit !== undefined) {
        const totalCacheableQueries = this.stats.totalQueries; // Simplified
        const cacheHits = cacheHit ? 1 : 0;
        this.stats.cacheHitRate =
          (this.stats.cacheHitRate * (totalCacheableQueries - 1) +
            cacheHits * 100) /
          totalCacheableQueries;
      }
    } catch (_error) {
      this.logger.error(
        `Failed to record database metrics: ${_error instanceof Error ? _error.message : 'Unknown error'}`,
      );
    }
  }

  /**
   * Record slow query for analysis
   */
  private recordSlowQuery(
    operation: DatabaseOperation,
    duration: number,
  ): void {
    const queryKey = `${operation.operation}:${operation.table}`;

    if (!this.slowQueries.has(queryKey)) {
      this.slowQueries.set(queryKey, {
        totalDuration: duration,
        count: 1,
        avgDuration: duration,
      });
    } else {
      const slowQuery = this.slowQueries.get(queryKey)!;
      slowQuery.totalDuration += duration;
      slowQuery.count++;
      slowQuery.avgDuration = slowQuery.totalDuration / slowQuery.count;
    }

    // Update top slow queries
    this.updateTopSlowQueries();
  }

  /**
   * Update top slow queries list
   */
  private updateTopSlowQueries(): void {
    this.stats.topSlowQueries = Array.from(this.slowQueries.entries())
      .map(([key, stats]) => {
        const [operation, table] = key.split(':');
        return {
          operation,
          table,
          avgDuration: stats.avgDuration,
          count: stats.count,
        };
      })
      .sort((a, b) => b.avgDuration - a.avgDuration)
      .slice(0, 10); // Top 10 slow queries
  }

  /**
   * Get current database statistics
   */
  getStats(): DatabaseStats {
    this.updateTopSlowQueries();
    return { ...this.stats };
  }

  /**
   * Clear database statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalQueries: 0,
      averageQueryTime: 0,
      slowQueries: 0,
      failedQueries: 0,
      cacheHitRate: 0,
      connectionPoolStats: {
        active: 0,
        idle: 0,
        total: 0,
      },
      topSlowQueries: [],
    });

    this.slowQueries.clear();
    this.logger.log('Database statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report database stats every 10 minutes
    setInterval(() => {
      if (this.stats.totalQueries > 0) {
        this.logger.log('Database Performance Statistics:', {
          totalQueries: this.stats.totalQueries,
          averageQueryTime: `${this.stats.averageQueryTime.toFixed(2)}ms`,
          slowQueries: this.stats.slowQueries,
          failedQueries: this.stats.failedQueries,
          cacheHitRate: `${this.stats.cacheHitRate.toFixed(2)}%`,
          topSlowQueries: this.stats.topSlowQueries.slice(0, 3),
        });
      }
    }, 600000); // 10 minutes
  }
}

/**
 * Logging Interceptor with Correlation ID Tracking
 *
 * NestJS interceptor providing comprehensive request/response logging with
 * correlation ID tracking for enterprise-grade observability. Enables
 * distributed tracing and structured JSON logging.
 *
 * Features:
 * - Correlation ID generation and propagation
 * - Structured JSON logging format
 * - Request/response timing
 * - Error tracking with stack traces
 * - Performance metrics integration
 * - User context tracking
 *
 * @author Claude Code
 * @version 1.0.0
 */

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import { Request, Response } from 'express';
import { v4 as _uuidv4 } from 'uuid';
import { MetricsService } from '../../metrics/metrics.service';

/**
 * Request context interface for structured logging
 */
export interface RequestContext {
  correlationId: string;
  method: string;
  url: string;
  userAgent?: string;
  remoteAddress: string;
  timestamp: string;
  userId?: string;
  sessionId?: string;
}

/**
 * Response context interface for structured logging
 */
export interface ResponseContext {
  statusCode: number;
  processingTime: number;
  contentLength?: number;
  cacheHit?: boolean;
}

/**
 * Error context interface for structured logging
 */
export interface ErrorContext {
  name: string;
  message: string;
  stack?: string;
  statusCode?: number;
}

/**
 * Comprehensive logging interceptor with correlation tracking
 */
@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger(LoggingInterceptor.name);

  constructor(private readonly metricsService?: MetricsService) {
    this.logger.log(
      'Logging Interceptor initialized - Structured logging enabled',
    );
  }

  /**
   * Intercept HTTP requests and responses for comprehensive logging
   *
   * @param context Execution context
   * @param next Call handler
   * @returns Observable with logging side effects
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const httpContext = context.switchToHttp();
    const request = httpContext.getRequest<Request>();
    const response = httpContext.getResponse<Response>();

    // Generate correlation ID
    const correlationId = this.generateCorrelationId(request);

    // Add correlation ID to request headers for downstream services
    request.headers['x-correlation-id'] = correlationId;
    response.setHeader('X-Correlation-ID', correlationId);

    // Create request context
    const requestContext = this.createRequestContext(request, correlationId);

    const startTime = Date.now();
    const route = this.extractRoute(request);

    // Log request start
    this.logRequest(requestContext);

    // Track request start metrics
    if (this.metricsService) {
      this.metricsService.recordRequestStart(request.method, route);
    }

    return next.handle().pipe(
      tap(() => {
        // Handle successful response
        const processingTime = Date.now() - startTime;
        const responseContext = this.createResponseContext(
          response,
          processingTime,
        );

        this.logResponse(requestContext, responseContext);

        // Record metrics for successful requests
        if (this.metricsService) {
          this.metricsService.recordApiRequestDuration(
            request.method,
            route,
            response.statusCode,
            processingTime,
          );
          this.metricsService.recordRequestEnd(request.method, route);
        }
      }),
      catchError((_error) => {
        // Handle error response
        const processingTime = Date.now() - startTime;
        const responseContext = this.createResponseContext(
          response,
          processingTime,
        );
        const errorContext = this.createErrorContext(_error);

        this.logError(requestContext, responseContext, errorContext);

        // Record metrics for failed requests
        if (this.metricsService) {
          const statusCode = error?.status || error?.statusCode || 500;
          this.metricsService.recordApiRequestDuration(
            request.method,
            route,
            statusCode,
            processingTime,
          );
          this.metricsService.recordRequestEnd(request.method, route);
        }

        // Re-throw the error to maintain normal error handling
        throw error;
      }),
    );
  }

  /**
   * Generate or retrieve correlation ID from request
   *
   * @param request HTTP request object
   * @returns Correlation ID string
   */
  private generateCorrelationId(request: Request): string {
    // Check if correlation ID already exists (from upstream service)
    const existingId =
      request.headers['x-correlation-id'] ||
      request.headers['x-request-id'] ||
      request.headers['x-trace-id'];

    return (existingId as string) || uuidv4();
  }

  /**
   * Create structured request context
   *
   * @param request HTTP request object
   * @param correlationId Request correlation ID
   * @returns Request context object
   */
  private createRequestContext(
    request: Request,
    correlationId: string,
  ): RequestContext {
    return {
      correlationId,
      method: request.method,
      url: request.originalUrl || request.url,
      userAgent: request.headers['user-agent'],
      remoteAddress: this.getClientIpAddress(request),
      timestamp: new Date().toISOString(),
      userId: (request as Request & { user?: { id: string } }).user?.id, // If authentication is implemented
      sessionId: (request as Request & { session?: { id: string } }).session
        ?.id, // If sessions are used
    };
  }

  /**
   * Create structured response context
   *
   * @param response HTTP response object
   * @param processingTime Request processing time in milliseconds
   * @returns Response context object
   */
  private createResponseContext(
    response: Response,
    processingTime: number,
  ): ResponseContext {
    return {
      statusCode: response.statusCode,
      processingTime,
      contentLength:
        parseInt(response.get('Content-Length') || '0', 10) || undefined,
      cacheHit: response.get('X-Cache-Status') === 'HIT',
    };
  }

  /**
   * Create structured error context
   *
   * @param error Error object
   * @returns Error context object
   */
  private createErrorContext(error: Error): ErrorContext {
    return {
      name: error?.name || 'UnknownError',
      message: error?.message || 'An unknown error occurred',
      stack: error?.stack,
      statusCode:
        'status' in error && typeof error.status === 'number'
          ? error.status
          : 'statusCode' in error && typeof error.statusCode === 'number'
            ? error.statusCode
            : undefined,
    };
  }

  /**
   * Extract route pattern from request
   *
   * @param request HTTP request object
   * @returns Route pattern string
   */
  private extractRoute(request: Request): string {
    // Try to get route pattern from NestJS route info
    const routePattern = (request as Request & { route?: { path: string } })
      .route?.path;
    if (routePattern) {
      return routePattern;
    }

    // Fallback to URL path with parameter normalization
    const url = request.originalUrl || request.url;
    return this.normalizeUrlForMetrics(url);
  }

  /**
   * Normalize URL path for consistent metrics grouping
   *
   * @param url Original URL
   * @returns Normalized URL pattern
   */
  private normalizeUrlForMetrics(url: string): string {
    // Remove query parameters
    const path = url.split('?')[0];

    // Replace common ID patterns with placeholders
    return path
      .replace(/\/\d+/g, '/:id') // Replace numeric IDs
      .replace(/\/[a-f0-9-]{36}/g, '/:uuid') // Replace UUIDs
      .replace(/\/[a-f0-9]{24}/g, '/:objectId') // Replace MongoDB ObjectIDs
      .replace(/\/$/, ''); // Remove trailing slash
  }

  /**
   * Get client IP address from request
   *
   * @param request HTTP request object
   * @returns Client IP address
   */
  private getClientIpAddress(request: Request): string {
    return (request.headers['x-forwarded-for'] ||
      request.headers['x-real-ip'] ||
      request.connection?.remoteAddress ||
      request.socket?.remoteAddress ||
      'unknown') as string;
  }

  /**
   * Log successful request
   *
   * @param requestContext Request context information
   */
  private logRequest(requestContext: RequestContext): void {
    this.logger.log({
      message: 'HTTP Request Started',
      level: 'info',
      type: 'http_request',
      context: requestContext,
      timestamp: requestContext.timestamp,
    });
  }

  /**
   * Log successful response
   *
   * @param requestContext Request context information
   * @param responseContext Response context information
   */
  private logResponse(
    requestContext: RequestContext,
    responseContext: ResponseContext,
  ): void {
    const logLevel = responseContext.statusCode >= 400 ? 'warn' : 'info';
    const message = `HTTP Request Completed - ${requestContext.method} ${requestContext.url} - ${responseContext.statusCode}`;

    this.logger[logLevel]({
      message,
      level: logLevel,
      type: 'http_response',
      context: {
        request: requestContext,
        response: responseContext,
      },
      timestamp: new Date().toISOString(),
    });
  }

  /**
   * Log error response
   *
   * @param requestContext Request context information
   * @param responseContext Response context information
   * @param errorContext Error context information
   */
  private logError(
    requestContext: RequestContext,
    responseContext: ResponseContext,
    errorContext: ErrorContext,
  ): void {
    this.logger.error({
      message: `HTTP Request Failed - ${requestContext.method} ${requestContext.url} - ${errorContext.name}`,
      level: 'error',
      type: 'http_error',
      context: {
        request: requestContext,
        response: responseContext,
        error: errorContext,
      },
      timestamp: new Date().toISOString(),
    });
  }
}

/**
 * Performance Interceptor - Response Time Tracking and Monitoring
 *
 * Provides comprehensive performance monitoring for API endpoints with
 * automatic metrics collection, slow query detection, and performance
 * alerting. Designed for enterprise-grade observability.
 *
 * Features:
 * - Response time tracking with percentile metrics
 * - Slow endpoint detection and alerting
 * - Memory usage monitoring per request
 * - Database query performance tracking
 * - Comprehensive logging with operation IDs
 * - Prometheus metrics integration
 * - Performance baseline establishment
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, tap, catchError } from 'rxjs';
import { Request, Response } from 'express';
import { MetricsService } from '../../metrics/metrics.service';

/**
 * Performance monitoring data for each request
 */
interface PerformanceMetrics {
  operationId: string;
  startTime: number;
  endTime: number;
  duration: number;
  method: string;
  url: string;
  statusCode: number;
  memoryBefore: NodeJS.MemoryUsage;
  memoryAfter: NodeJS.MemoryUsage;
  memoryDelta: {
    rss: number;
    heapTotal: number;
    heapUsed: number;
    external: number;
  };
}

/**
 * Performance warning thresholds
 */
interface PerformanceThresholds {
  slowRequestWarning: number; // ms
  slowRequestCritical: number; // ms
  memoryLeakWarning: number; // bytes
  memoryUsageWarning: number; // percentage
}

/**
 * Performance statistics tracking
 */
interface PerformanceStats {
  requestCount: number;
  averageResponseTime: number;
  slowRequests: number;
  memoryAlerts: number;
  p50ResponseTime: number;
  p90ResponseTime: number;
  p95ResponseTime: number;
  p99ResponseTime: number;
}

/**
 * Performance monitoring interceptor
 */
@Injectable()
export class PerformanceInterceptor implements NestInterceptor {
  private readonly logger = new Logger(PerformanceInterceptor.name);
  private readonly responseTimes: number[] = [];
  private readonly stats: PerformanceStats = {
    requestCount: 0,
    averageResponseTime: 0,
    slowRequests: 0,
    memoryAlerts: 0,
    p50ResponseTime: 0,
    p90ResponseTime: 0,
    p95ResponseTime: 0,
    p99ResponseTime: 0,
  };

  // Performance thresholds (configurable via environment variables)
  private readonly thresholds: PerformanceThresholds = {
    slowRequestWarning: parseInt(
      process.env.SLOW_REQUEST_WARNING || '1000',
      10,
    ), // 1 second
    slowRequestCritical: parseInt(
      process.env.SLOW_REQUEST_CRITICAL || '5000',
      10,
    ), // 5 seconds
    memoryLeakWarning: parseInt(
      process.env.MEMORY_LEAK_WARNING || '50000000',
      10,
    ), // 50MB
    memoryUsageWarning: parseInt(process.env.MEMORY_USAGE_WARNING || '80', 10), // 80%
  };

  constructor(private readonly metricsService?: MetricsService) {
    this.logger.log('Performance Interceptor initialized');
    this.logger.log(
      `Thresholds: warning=${this.thresholds.slowRequestWarning}ms, critical=${this.thresholds.slowRequestCritical}ms`,
    );

    // Start periodic stats reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept HTTP requests to monitor performance
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    // Generate unique operation ID for request tracking
    const operationId = `perf_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    const startTime = Date.now();
    const memoryBefore = process.memoryUsage();

    // Add operation ID to request for downstream services
    (request as Request & { operationId?: string }).operationId = operationId;

    this.logger.debug(
      `[${operationId}] Performance monitoring started: ${request.method} ${request.url}`,
    );

    return next.handle().pipe(
      tap((_data) => {
        // Request completed successfully
        this.recordPerformanceMetrics({
          operationId,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          method: request.method,
          url: request.url,
          statusCode: response.statusCode,
          memoryBefore,
          memoryAfter: process.memoryUsage(),
          memoryDelta: this.calculateMemoryDelta(
            memoryBefore,
            process.memoryUsage(),
          ),
        });
      }),
      catchError((_error) => {
        // Request failed - still record performance metrics
        this.recordPerformanceMetrics({
          operationId,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          method: request.method,
          url: request.url,
          statusCode: response.statusCode || 500,
          memoryBefore,
          memoryAfter: process.memoryUsage(),
          memoryDelta: this.calculateMemoryDelta(
            memoryBefore,
            process.memoryUsage(),
          ),
        });

        throw error; // Re-throw the error
      }),
    );
  }

  /**
   * Record comprehensive performance metrics for the request
   */
  private recordPerformanceMetrics(metrics: PerformanceMetrics): void {
    try {
      // Log performance information
      this.logPerformanceMetrics(metrics);

      // Record metrics in MetricsService
      if (this.metricsService) {
        this.metricsService.recordApiRequestDuration(
          metrics.method,
          this.normalizeUrl(metrics.url),
          metrics.statusCode,
          metrics.duration,
        );
      }

      // Update internal statistics
      this.updateStats(metrics);

      // Check for performance warnings
      this.checkPerformanceThresholds(metrics);

      // Store response time for percentile calculations
      this.storeResponseTime(metrics.duration);
    } catch (_error) {
      this.logger.error(
        `[${metrics.operationId}] Failed to record performance metrics: ${error instanceof Error ? _error.message : 'Unknown error'}`,
      );
    }
  }

  /**
   * Log detailed performance metrics
   */
  private logPerformanceMetrics(metrics: PerformanceMetrics): void {
    const logLevel = this.determineLogLevel(metrics.duration);
    const logData = {
      operationId: metrics.operationId,
      method: metrics.method,
      url: metrics.url,
      statusCode: metrics.statusCode,
      duration: `${metrics.duration}ms`,
      memoryDelta: {
        rss: `${(metrics.memoryDelta.rss / 1024 / 1024).toFixed(2)}MB`,
        heapUsed: `${(metrics.memoryDelta.heapUsed / 1024 / 1024).toFixed(2)}MB`,
      },
    };

    switch (logLevel) {
      case 'debug':
        this.logger.debug(
          `[${metrics.operationId}] Request completed`,
          logData,
        );
        break;
      case 'log':
        this.logger.log(`[${metrics.operationId}] Request completed`, logData);
        break;
      case 'warn':
        this.logger.warn(
          `[${metrics.operationId}] Slow request detected`,
          logData,
        );
        break;
      case 'error':
        this.logger.error(
          `[${metrics.operationId}] Critical slow request`,
          logData,
        );
        break;
    }
  }

  /**
   * Determine appropriate log level based on response time
   */
  private determineLogLevel(
    duration: number,
  ): 'debug' | 'log' | 'warn' | 'error' {
    if (duration >= this.thresholds.slowRequestCritical) {
      return 'error';
    } else if (duration >= this.thresholds.slowRequestWarning) {
      return 'warn';
    } else if (duration >= 500) {
      return 'log';
    } else {
      return 'debug';
    }
  }

  /**
   * Check performance thresholds and generate alerts
   */
  private checkPerformanceThresholds(metrics: PerformanceMetrics): void {
    // Check response time thresholds
    if (metrics.duration >= this.thresholds.slowRequestCritical) {
      this.stats.slowRequests++;
      this.logger.error(
        `[${metrics.operationId}] CRITICAL: Request exceeded ${this.thresholds.slowRequestCritical}ms threshold`,
        {
          duration: metrics.duration,
          url: metrics.url,
          method: metrics.method,
        },
      );
    } else if (metrics.duration >= this.thresholds.slowRequestWarning) {
      this.stats.slowRequests++;
      this.logger.warn(
        `[${metrics.operationId}] WARNING: Request exceeded ${this.thresholds.slowRequestWarning}ms threshold`,
        {
          duration: metrics.duration,
          url: metrics.url,
          method: metrics.method,
        },
      );
    }

    // Check memory usage thresholds
    const memoryIncrease = Math.max(
      metrics.memoryDelta.rss,
      metrics.memoryDelta.heapUsed,
    );

    if (memoryIncrease > this.thresholds.memoryLeakWarning) {
      this.stats.memoryAlerts++;
      this.logger.warn(`[${metrics.operationId}] Memory usage spike detected`, {
        memoryDelta: metrics.memoryDelta,
        url: metrics.url,
        method: metrics.method,
      });
    }
  }

  /**
   * Calculate memory usage delta
   */
  private calculateMemoryDelta(
    before: NodeJS.MemoryUsage,
    after: NodeJS.MemoryUsage,
  ): PerformanceMetrics['memoryDelta'] {
    return {
      rss: after.rss - before.rss,
      heapTotal: after.heapTotal - before.heapTotal,
      heapUsed: after.heapUsed - before.heapUsed,
      external: after.external - before.external,
    };
  }

  /**
   * Normalize URL for consistent metrics grouping
   */
  private normalizeUrl(url: string): string {
    // Remove query parameters and normalize path parameters
    return url
      .split('?')[0] // Remove query string
      .replace(/\/\d+/g, '/:id') // Replace numeric path params
      .replace(/\/[a-f0-9-]{36}/g, '/:uuid') // Replace UUID path params
      .replace(/\/[a-f0-9]{24}/g, '/:objectid'); // Replace MongoDB ObjectId path params
  }

  /**
   * Store response time for percentile calculations
   */
  private storeResponseTime(duration: number): void {
    this.responseTimes.push(duration);

    // Keep only last 1000 response times to prevent memory bloat
    if (this.responseTimes.length > 1000) {
      this.responseTimes.shift();
    }

    // Recalculate percentiles periodically
    if (this.responseTimes.length % 50 === 0) {
      this.calculatePercentiles();
    }
  }

  /**
   * Calculate response time percentiles
   */
  private calculatePercentiles(): void {
    if (this.responseTimes.length === 0) return;

    const sortedTimes = [...this.responseTimes].sort((a, b) => a - b);
    const _length = sortedTimes.length;

    this.stats.p50ResponseTime = this.getPercentile(sortedTimes, 50);
    this.stats.p90ResponseTime = this.getPercentile(sortedTimes, 90);
    this.stats.p95ResponseTime = this.getPercentile(sortedTimes, 95);
    this.stats.p99ResponseTime = this.getPercentile(sortedTimes, 99);
  }

  /**
   * Get specific percentile from sorted array
   */
  private getPercentile(sortedArray: number[], percentile: number): number {
    const _index = Math.ceil((percentile / 100) * sortedArray.length) - 1;
    return sortedArray[Math.max(0, _index)];
  }

  /**
   * Update internal performance statistics
   */
  private updateStats(metrics: PerformanceMetrics): void {
    this.stats.requestCount++;

    // Update average response time
    this.stats.averageResponseTime =
      (this.stats.averageResponseTime * (this.stats.requestCount - 1) +
        metrics.duration) /
      this.stats.requestCount;
  }

  /**
   * Get current performance statistics
   */
  getStats(): PerformanceStats {
    this.calculatePercentiles();
    return { ...this.stats };
  }

  /**
   * Clear performance statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      requestCount: 0,
      averageResponseTime: 0,
      slowRequests: 0,
      memoryAlerts: 0,
      p50ResponseTime: 0,
      p90ResponseTime: 0,
      p95ResponseTime: 0,
      p99ResponseTime: 0,
    });

    this.responseTimes.length = 0;
    this.logger.log('Performance statistics cleared');
  }

  /**
   * Start periodic performance statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report stats every 5 minutes
    setInterval(() => {
      if (this.stats.requestCount > 0) {
        this.calculatePercentiles();

        this.logger.log('Performance Statistics Summary:', {
          requestCount: this.stats.requestCount,
          averageResponseTime: `${this.stats.averageResponseTime.toFixed(2)}ms`,
          slowRequests: this.stats.slowRequests,
          memoryAlerts: this.stats.memoryAlerts,
          percentiles: {
            p50: `${this.stats.p50ResponseTime}ms`,
            p90: `${this.stats.p90ResponseTime}ms`,
            p95: `${this.stats.p95ResponseTime}ms`,
            p99: `${this.stats.p99ResponseTime}ms`,
          },
        });
      }
    }, 300000); // 5 minutes
  }
}

// @ts-nocheck
/**
 * Security Headers Middleware - Comprehensive HTTP Security Headers for BytebotD
 *
 * This middleware implements enterprise-grade security headers using helmet.js
 * with production-ready configurations for CSP, HSTS, CORS, and other security
 * headers. Includes environment-specific configurations and security monitoring.
 *
 * @fileoverview Enterprise security headers middleware for BytebotD service
 * @version 1.0.0
 * @author Security Headers & CORS Specialist
 */

import { Injectable, NestMiddleware, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import { SecurityEventType, createSecurityEvent } from '@bytebot/shared';

/**
 * Security headers configuration interface
 */
interface SecurityMiddlewareConfig {
  /** Environment (development, staging, production) */
  environment: string;

  /** Enable Content Security Policy */
  csp: boolean;

  /** CSP directives */
  cspDirectives?: Record<string, string[]>;

  /** Enable HSTS */
  hsts: boolean;

  /** HSTS max age in seconds */
  hstsMaxAge: number;

  /** Include subdomains in HSTS */
  hstsIncludeSubDomains: boolean;

  /** Enable HSTS preload */
  hstsPreload: boolean;

  /** Frame options value */
  frameOptions: 'DENY' | 'SAMEORIGIN' | false;

  /** Enable X-Content-Type-Options: nosniff */
  noSniff: boolean;

  /** Enable X-XSS-Protection */
  xssFilter: boolean;

  /** Enable referrer policy */
  referrerPolicy: string | false;

  /** Allowed CORS origins */
  corsOrigins: string[] | string;

  /** CORS credentials */
  corsCredentials: boolean;

  /** Custom security headers */
  customHeaders?: Record<string, string>;

  /** Enable security event logging */
  enableSecurityLogging: boolean;

  /** Trusted proxies for IP detection */
  trustedProxies?: string[];
}

/**
 * Default security configurations by environment
 */
const SECURITY_CONFIGS: Record<string, Partial<SecurityMiddlewareConfig>> = {
  development: {
    csp: false, // Relaxed CSP for development
    hsts: false, // No HSTS in development
    frameOptions: 'SAMEORIGIN',
    corsOrigins: [
      'http://localhost:3000',
      'http://localhost:3001',
      'http://localhost:8080',
    ],
    corsCredentials: true,
    enableSecurityLogging: false,
  },

  staging: {
    csp: true,
    hsts: true,
    hstsMaxAge: 86400, // 1 day
    hstsIncludeSubDomains: true,
    hstsPreload: false,
    frameOptions: 'DENY',
    corsCredentials: true,
    enableSecurityLogging: true,
  },

  production: {
    csp: true,
    hsts: true,
    hstsMaxAge: 31536000, // 1 year
    hstsIncludeSubDomains: true,
    hstsPreload: true,
    frameOptions: 'DENY',
    corsCredentials: true,
    enableSecurityLogging: true,
    customHeaders: {
      'X-Powered-By': '', // Remove X-Powered-By header
      Server: '', // Remove Server header
      'X-Service': 'BytebotD',
      'X-API-Version': '1.0',
    },
